    growmzcb = growmzcb + r_mzpom*pommzcb
    CALL POPCONTROL1B(branch)
    IF (branch .EQ. 0) remimzpb = 0.D0
    CALL POPCONTROL1B(branch)
    IF (branch .EQ. 0) THEN
      r_mzremib = (y(imzp)-q_mz_p*(y(imzn)/q_mz_n))*remimzpb
      yb(imzp) = yb(imzp) + r_mzremi*remimzpb
      yb(imzn) = yb(imzn) - q_mz_p*r_mzremi*remimzpb/q_mz_n
    ELSE
      r_mzremib = (y(imzp)-q_mz_p*y(imzc))*remimzpb
      yb(imzp) = yb(imzp) + r_mzremi*remimzpb
      yb(imzc) = yb(imzc) - q_mz_p*r_mzremi*remimzpb
    END IF
    tempb4 = remimz15nb/(beta_mz_remi+1.0d0)
    remimznb = remimznb + beta_mz_remi*tempb4
    beta_mz_remib = (remimzn-remimzn*beta_mz_remi/(beta_mz_remi+1.0d0))*&
&     tempb4
    rmzb = rmzb + (1.0d0-epsilon_remin/1000.0d0)*beta_mz_remib
    epsilon_reminb = epsilon_reminb - rmz*beta_mz_remib/1000.0d0
    CALL POPCONTROL1B(branch)
    IF (branch .EQ. 0) remimznb = 0.D0
    CALL POPCONTROL1B(branch)
    IF (branch .EQ. 0) THEN
      r_mzremib = r_mzremib + (y(imzn)-q_mz_n*(y(imzp)/q_mz_p))*remimznb
      yb(imzn) = yb(imzn) + r_mzremi*remimznb
      yb(imzp) = yb(imzp) - q_mz_n*r_mzremi*remimznb/q_mz_p
    ELSE
      r_mzremib = r_mzremib + (y(imzn)-q_mz_n*y(imzc))*remimznb
      yb(imzn) = yb(imzn) + r_mzremi*remimznb
      yb(imzc) = yb(imzc) - q_mz_n*r_mzremi*remimznb
    END IF
    tempb4 = 0.5d0*excrmzsdom2pb/y(imzc)
    excrmzsdom2cb = excrmzsdom2cb + y(imzp)*tempb4
    yb(imzp) = yb(imzp) + excrmzsdom2c*tempb4
    yb(imzc) = yb(imzc) - excrmzsdom2c*y(imzp)*tempb4/y(imzc)
    tempb4 = excrmzsdom2_15nb/(rmz+1.0d0)
    excrmzsdom2nb = excrmzsdom2nb + rmz*tempb4
    rmzb = rmzb + (excrmzsdom2n-excrmzsdom2n*rmz/(rmz+1.0d0))*tempb4
    tempb4 = 0.5d0*excrmzsdom2nb/y(imzc)
    excrmzsdom2cb = excrmzsdom2cb + y(imzn)*tempb4
    yb(imzn) = yb(imzn) + excrmzsdom2c*tempb4
    yb(imzc) = yb(imzc) + r_mzadju*temp*excrmzsdom2cb - excrmzsdom2c*y(&
&     imzn)*tempb4/y(imzc)
    r_mzadjub = temp*y(imzc)*excrmzsdom2cb
    tempb = r_mzadju*y(imzc)*excrmzsdom2cb
    CALL POPCONTROL1B(branch)
    IF (branch .EQ. 0) tempb = 0.D0
    CALL POPCONTROL1B(branch)
    IF (branch .EQ. 0) THEN
      CALL POPREAL8(temp)
      tempb4 = -(tempb/(q_mz_p*y(imzc)))
      yb(imzp) = yb(imzp) + tempb4
      yb(imzc) = yb(imzc) - y(imzp)*tempb4/y(imzc)
    ELSE
      CALL POPREAL8(temp)
      tempb4 = -(tempb/(q_mz_n*y(imzc)))
      yb(imzn) = yb(imzn) + tempb4
      yb(imzc) = yb(imzc) - y(imzn)*tempb4/y(imzc)
    END IF
    r_mzresp_1b = y(imzc)*respmzb
    yb(imzc) = yb(imzc) + r_mzresp_1*respmzb
    r_mzresp_2b = growmzc*respmzb
    growmzcb = growmzcb + r_mzresp_2*respmzb + r_mzex*(c1-f_exmzldom)*&
&     excrmzsdomcb + f_exmzldom*r_mzex*excrmzldomcb
    temp5 = r_mzex*growmzp/(q_mz_p*y(imzc))
    f_exmzldomb = -(y(imzp)*temp5*excrmzsdompb)
    yb(imzp) = yb(imzp) + (c1-f_exmzldom)*temp5*excrmzsdompb
    tempb4 = (c1-f_exmzldom)*y(imzp)*excrmzsdompb/(q_mz_p*y(imzc))
    r_mzexb = growmzp*tempb4
    growmzpb = growmzpb + r_mzex*tempb4 + f_exmzldom*r_mzex*excrmzldompb
    yb(imzc) = yb(imzc) - q_mz_p*temp5*tempb4
    tempb4 = excrmzsdom15nb/(rmz+1.0d0)
    excrmzsdomnb = excrmzsdomnb + rmz*tempb4
    rmzb = rmzb + (excrmzsdomn-excrmzsdomn*rmz/(rmz+1.0d0))*tempb4
    temp5 = r_mzex*growmzn/(q_mz_n*y(imzc))
    f_exmzldomb = f_exmzldomb + r_mzex*growmzp*excrmzldompb - y(imzn)*&
&     temp5*excrmzsdomnb - r_mzex*growmzc*excrmzsdomcb + r_mzex*&
&     growmz15n*excrmzldom15nb + r_mzex*growmzn*excrmzldomnb + r_mzex*&
&     growmzc*excrmzldomcb
    yb(imzn) = yb(imzn) + (c1-f_exmzldom)*temp5*excrmzsdomnb
    tempb4 = (c1-f_exmzldom)*y(imzn)*excrmzsdomnb/(q_mz_n*y(imzc))
    r_mzexb = r_mzexb + growmzn*tempb4 + growmzc*(c1-f_exmzldom)*&
&     excrmzsdomcb + f_exmzldom*growmzp*excrmzldompb + f_exmzldom*&
&     growmz15n*excrmzldom15nb + f_exmzldom*growmzn*excrmzldomnb + &
&     f_exmzldom*growmzc*excrmzldomcb
    growmznb = growmznb + r_mzex*tempb4 + f_exmzldom*r_mzex*excrmzldomnb
    yb(imzc) = yb(imzc) - q_mz_n*temp5*tempb4
    growmz15nb = growmz15nb + f_exmzldom*r_mzex*excrmzldom15nb
    graztrpb = graztrpb + growmzpb
    grazddapb = grazddapb + growmzpb
    graztr15nb = graztr15nb + growmz15nb
    grazdda15nb = grazdda15nb + growmz15nb
    graztrnb = graztrnb + growmznb
    grazddanb = grazddanb + growmznb
    graztrcb = graztrcb + growmzcb
    grazddacb = grazddacb + growmzcb
    tempb4 = dydttb(iprtp)/secperday
    grazprtpb = grazprtpb + growmzpb - tempb4
    dydttb(iprtp) = 0.D0
    growprtpb = growprtpb + tempb4
    excrprtldompb = excrprtldompb - tempb4
    excrprtsdompb = excrprtsdompb - tempb4
    excrprtsdom2pb = excrprtsdom2pb - tempb4
    remiprtpb = remiprtpb - tempb4
    pomprtpb = pomprtpb - tempb4
    tempb4 = dydttb(iprt15n)/secperday
    grazprt15nb = grazprt15nb + growmz15nb - tempb4
    dydttb(iprt15n) = 0.D0
    growprt15nb = growprt15nb + tempb4
    excrprtldom15nb = excrprtldom15nb - tempb4
    excrprtsdom15nb = excrprtsdom15nb - tempb4
    excrprtsdom2_15nb = excrprtsdom2_15nb - tempb4
    remiprt15nb = remiprt15nb - tempb4
    pomprt15nb = pomprt15nb - tempb4
    tempb4 = dydttb(iprtn)/secperday
    grazprtnb = grazprtnb + growmznb - tempb4
    dydttb(iprtn) = 0.D0
    growprtnb = growprtnb + tempb4
    excrprtldomnb = excrprtldomnb - tempb4
    excrprtsdomnb = excrprtsdomnb - tempb4
    excrprtsdom2nb = excrprtsdom2nb - tempb4
    remiprtnb = remiprtnb - tempb4
    pomprtnb = pomprtnb - tempb4
    tempb4 = dydttb(iprtc)/secperday
    grazprtcb = grazprtcb + growmzcb - tempb4
    dydttb(iprtc) = 0.D0
    growprtcb = growprtcb + tempb4
    excrprtldomcb = excrprtldomcb - tempb4
    excrprtsdomcb = excrprtsdomcb - tempb4
    excrprtsdom2cb = excrprtsdom2cb - tempb4
    pomprtcb = pomprtcb - tempb4
    respprtb = respprtb - tempb4
    tempb4 = grazprtpb/y(iprtc)
    grazprtcb = grazprtcb + y(iprtp)*tempb4
    yb(iprtp) = yb(iprtp) + grazprtc*tempb4
    yb(iprtc) = yb(iprtc) - grazprtc*y(iprtp)*tempb4/y(iprtc)
    tempb4 = grazprt15nb/(beta_prt_graz+1.0d0)
    grazprtnb = grazprtnb + beta_prt_graz*tempb4
    beta_prt_grazb = (grazprtn-grazprtn*beta_prt_graz/(beta_prt_graz+&
&     1.0d0))*tempb4
    rprtb = (1.0d0-epsilon_g/1000.0d0*factor_prt_graz)*beta_prt_grazb
    epsilon_gb = -(factor_prt_graz*rprt*beta_prt_grazb/1000.0d0)
    factor_prt_grazb = -(epsilon_g*rprt*beta_prt_grazb/1000.0d0)
    CALL POPCONTROL1B(branch)
    IF (branch .EQ. 0) THEN
      temp5 = (-u_prt_graz+1.0d0)/u_prt_graz
      tempb4 = -(LOG(1.0d0-u_prt_graz)*factor_prt_grazb/u_prt_graz)
      u_prt_grazb = temp5*factor_prt_grazb/(1.0d0-u_prt_graz) - (temp5+&
&       1.0)*tempb4
    ELSE
      u_prt_grazb = 0.D0
    END IF
    CALL POPCONTROL1B(branch)
    IF (branch .EQ. 0) THEN
      y24b = u_prt_grazb
    ELSE
      y24b = 0.D0
    END IF
    CALL POPCONTROL1B(branch)
    IF (branch .EQ. 0) THEN
      u_prt_grazb = y24b
    ELSE
      u_prt_grazb = 0.D0
    END IF
    tempb4 = dt*u_prt_grazb/(eps+y(iprtn))
    grazprtnb = grazprtnb + tempb4
    yb(iprtn) = yb(iprtn) - grazprtn*tempb4/(eps+y(iprtn))
    tempb4 = grazprtnb/y(iprtc)
    grazprtcb = grazprtcb + y(iprtn)*tempb4
    yb(iprtn) = yb(iprtn) + grazprtc*tempb4
    yb(iprtc) = yb(iprtc) - grazprtc*y(iprtn)*tempb4/y(iprtc)
    temp5 = g_prt*g_prt/(g_dda*g_dda)
    temp4 = g_prt*g_prt/(g_tr*g_tr)
    temp3 = y(iprtc)*y(iprtc) + g_prt*g_prt + y(itrc)*y(itrc)*temp4 + y(&
&     iddac)*y(iddac)*temp5
    temp0 = y(iprtc)*y(iprtc)
    tempb1 = grazprtcb/temp3
    mu_mzb = y(imzc)*temp0*tempb1
    yb(imzc) = yb(imzc) + mu_mz*temp0*tempb1
    tempb2 = -(mu_mz*y(imzc)*temp0*tempb1/temp3)
    yb(iprtc) = yb(iprtc) + 2*y(iprtc)*mu_mz*y(imzc)*tempb1 + 2*y(iprtc)&
&     *tempb2
    yb(itrc) = yb(itrc) + 2*y(itrc)*temp4*tempb2
    tempb3 = y(itrc)**2*tempb2/g_tr**2
    yb(iddac) = yb(iddac) + 2*y(iddac)*temp5*tempb2
    tempb4 = y(iddac)**2*tempb2/g_dda**2
    g_prtb = 2*g_prt*tempb2 + 2*g_prt*tempb4 + 2*g_prt*tempb3
    g_ddab = -(2*g_dda*temp5*tempb4)
    g_trb = -(2*g_tr*temp4*tempb3)
    q_pom_pb = q_pom_pb + pomprtc*pomprtpb
    tempb4 = pomprt15nb/(rprt+1.0d0)
    pomprtnb = pomprtnb + rprt*tempb4
    pomprtcb = pomprtcb + q_pom_p*pomprtpb + q_pom_n*pomprtnb
    rprtb = rprtb + (pomprtn-pomprtn*rprt/(rprt+1.0d0))*tempb4
    q_pom_nb = q_pom_nb + pomprtc*pomprtnb
    r_pomprtb = growprtc*pomprtcb
    growprtcb = growprtcb + r_pomprt*pomprtcb
    CALL POPCONTROL1B(branch)
    IF (branch .NE. 0) remiprtpb = 0.D0
    CALL POPCONTROL1B(branch)
    IF (branch .EQ. 0) THEN
      r_prtremib = (y(iprtp)-q_prt_p*(y(iprtn)/q_prt_n))*remiprtpb
      yb(iprtp) = yb(iprtp) + r_prtremi*remiprtpb
      yb(iprtn) = yb(iprtn) - q_prt_p*r_prtremi*remiprtpb/q_prt_n
    ELSE
      r_prtremib = (y(iprtp)-q_prt_p*y(iprtc))*remiprtpb
      yb(iprtp) = yb(iprtp) + r_prtremi*remiprtpb
      yb(iprtc) = yb(iprtc) - q_prt_p*r_prtremi*remiprtpb
    END IF
    tempb4 = remiprt15nb/(beta_prt_remi+1.0d0)
    remiprtnb = remiprtnb + beta_prt_remi*tempb4
    beta_prt_remib = (remiprtn-remiprtn*beta_prt_remi/(beta_prt_remi+&
&     1.0d0))*tempb4
    rprtb = rprtb + (1.0d0-epsilon_remin/1000.0d0)*beta_prt_remib
    epsilon_reminb = epsilon_reminb - rprt*beta_prt_remib/1000.0d0
    CALL POPCONTROL1B(branch)
    IF (branch .NE. 0) remiprtnb = 0.D0
    CALL POPCONTROL1B(branch)
    IF (branch .EQ. 0) THEN
      r_prtremib = r_prtremib + (y(iprtn)-q_prt_n*(y(iprtp)/q_prt_p))*&
&       remiprtnb
      yb(iprtn) = yb(iprtn) + r_prtremi*remiprtnb
      yb(iprtp) = yb(iprtp) - q_prt_n*r_prtremi*remiprtnb/q_prt_p
    ELSE
      r_prtremib = r_prtremib + (y(iprtn)-q_prt_n*y(iprtc))*remiprtnb
      yb(iprtn) = yb(iprtn) + r_prtremi*remiprtnb
      yb(iprtc) = yb(iprtc) - q_prt_n*r_prtremi*remiprtnb
    END IF
    tempb4 = 0.5d0*excrprtsdom2pb/y(iprtc)
    excrprtsdom2cb = excrprtsdom2cb + y(iprtp)*tempb4
    yb(iprtp) = yb(iprtp) + excrprtsdom2c*tempb4
    yb(iprtc) = yb(iprtc) - excrprtsdom2c*y(iprtp)*tempb4/y(iprtc)
    tempb4 = excrprtsdom2_15nb/(rprt+1.0d0)
    excrprtsdom2nb = excrprtsdom2nb + rprt*tempb4
    rprtb = rprtb + (excrprtsdom2n-excrprtsdom2n*rprt/(rprt+1.0d0))*&
&     tempb4
    tempb4 = 0.5d0*excrprtsdom2nb/y(iprtc)
    excrprtsdom2cb = excrprtsdom2cb + y(iprtn)*tempb4
    yb(iprtn) = yb(iprtn) + excrprtsdom2c*tempb4
    yb(iprtc) = yb(iprtc) + r_prtadju*temp*excrprtsdom2cb - &
&     excrprtsdom2c*y(iprtn)*tempb4/y(iprtc)
    r_prtadjub = temp*y(iprtc)*excrprtsdom2cb
    tempb = r_prtadju*y(iprtc)*excrprtsdom2cb
    CALL POPCONTROL1B(branch)
    IF (branch .NE. 0) tempb = 0.D0
    CALL POPCONTROL1B(branch)
    IF (branch .EQ. 0) THEN
      CALL POPREAL8(temp)
      tempb4 = -(tempb/(q_prt_p*y(iprtc)))
      yb(iprtp) = yb(iprtp) + tempb4
      yb(iprtc) = yb(iprtc) - y(iprtp)*tempb4/y(iprtc)
    ELSE
      CALL POPREAL8(temp)
      tempb4 = -(tempb/(q_prt_n*y(iprtc)))
      yb(iprtn) = yb(iprtn) + tempb4
      yb(iprtc) = yb(iprtc) - y(iprtn)*tempb4/y(iprtc)
    END IF
    r_prtresp_1b = y(iprtc)*respprtb
    yb(iprtc) = yb(iprtc) + r_prtresp_1*respprtb
    r_prtresp_2b = growprtc*respprtb
    growprtcb = growprtcb + r_prtresp_2*respprtb + r_prtex*(c1-&
&     f_exprtldom)*excrprtsdomcb + f_exprtldom*r_prtex*excrprtldomcb
    temp5 = r_prtex*growprtp/(q_prt_p*y(iprtc))
    f_exprtldomb = -(y(iprtp)*temp5*excrprtsdompb)
    yb(iprtp) = yb(iprtp) + (c1-f_exprtldom)*temp5*excrprtsdompb
    tempb4 = (c1-f_exprtldom)*y(iprtp)*excrprtsdompb/(q_prt_p*y(iprtc))
    r_prtexb = growprtp*tempb4
    growprtpb = growprtpb + r_prtex*tempb4 + f_exprtldom*r_prtex*&
&     excrprtldompb
    yb(iprtc) = yb(iprtc) - q_prt_p*temp5*tempb4
    tempb4 = excrprtsdom15nb/(rprt+1.0d0)
    excrprtsdomnb = excrprtsdomnb + rprt*tempb4
    rprtb = rprtb + (excrprtsdomn-excrprtsdomn*rprt/(rprt+1.0d0))*tempb4
    temp5 = r_prtex*growprtn/(q_prt_n*y(iprtc))
    f_exprtldomb = f_exprtldomb + r_prtex*growprtp*excrprtldompb - y(&
&     iprtn)*temp5*excrprtsdomnb - r_prtex*growprtc*excrprtsdomcb + &
&     r_prtex*growprt15n*excrprtldom15nb + r_prtex*growprtn*&
&     excrprtldomnb + r_prtex*growprtc*excrprtldomcb
    yb(iprtn) = yb(iprtn) + (c1-f_exprtldom)*temp5*excrprtsdomnb
    tempb4 = (c1-f_exprtldom)*y(iprtn)*excrprtsdomnb/(q_prt_n*y(iprtc))
    r_prtexb = r_prtexb + growprtn*tempb4 + growprtc*(c1-f_exprtldom)*&
&     excrprtsdomcb + f_exprtldom*growprtp*excrprtldompb + f_exprtldom*&
&     growprt15n*excrprtldom15nb + f_exprtldom*growprtn*excrprtldomnb + &
&     f_exprtldom*growprtc*excrprtldomcb
