&     excrprtldomnb
    yb(iprtc) = yb(iprtc) - q_prt_n*temp5*tempb4
    growprt15nb = growprt15nb + f_exprtldom*r_prtex*excrprtldom15nb
    grazsppb = grazsppb + growprtpb
    grazunpb = grazunpb + growprtpb
    grazsp15nb = grazsp15nb + growprt15nb
    grazun15nb = grazun15nb + growprt15nb
    grazspnb = grazspnb + growprtnb
    grazunnb = grazunnb + growprtnb
    grazspcb = grazspcb + growprtcb
    grazuncb = grazuncb + growprtcb
    growbapo4b = growbapo4b + fluxbapo4b
    growba15no3b = growba15no3b + fluxba15no3b
    growba15nh4b = growba15nh4b + fluxba15nh4b
    growbano3b = growbano3b + fluxbano3b
    growbanh4b = growbanh4b + fluxbanh4b
    tempb4 = dydttb(ibap)/secperday
    grazbapb = grazbapb + growprtpb - tempb4
    remibapb = remibapb - fluxbapo4b - tempb4
    dydttb(ibap) = 0.D0
    growbapb = growbapb + tempb4
    excrbapb = excrbapb - tempb4
    mortbapb = mortbapb - tempb4
    tempb4 = dydttb(iba15n)/secperday
    grazba15nb = grazba15nb + growprt15nb - tempb4
    remiba15nb = remiba15nb - fluxba15nh4b - tempb4
    dydttb(iba15n) = 0.D0
    growba15nb = growba15nb + tempb4
    excrba15nb = excrba15nb - tempb4
    mortba15nb = mortba15nb - tempb4
    tempb4 = dydttb(iban)/secperday
    grazbanb = grazbanb + growprtnb - tempb4
    remibanb = remibanb - fluxbanh4b - tempb4
    dydttb(iban) = 0.D0
    growbanb = growbanb + tempb4
    excrbanb = excrbanb - tempb4
    mortbanb = mortbanb - tempb4
    tempb4 = dydttb(ibac)/secperday
    grazbacb = grazbacb + growprtcb - tempb4
    dydttb(ibac) = 0.D0
    growbacb = growbacb + tempb4
    excrbacb = excrbacb - tempb4
    respbab = respbab - tempb4
    mortbacb = mortbacb - tempb4
    yb(ibap) = yb(ibap) + r_bamort*mortbapb
    tempb4 = mortba15nb/(rba+1.0d0)
    mortbanb = mortbanb + rba*tempb4
    r_bamortb = y(ibap)*mortbapb + y(iban)*mortbanb + y(ibac)*mortbacb
    rbab = (mortban-mortban*rba/(rba+1.0d0))*tempb4
    yb(iban) = yb(iban) + r_bamort*mortbanb
    yb(ibac) = yb(ibac) + r_bamort*mortbacb
    tempb4 = grazbapb/y(ibac)
    grazbacb = grazbacb + y(ibap)*tempb4
    yb(ibap) = yb(ibap) + grazbac*tempb4
    yb(ibac) = yb(ibac) - grazbac*y(ibap)*tempb4/y(ibac)
    tempb4 = grazba15nb/(beta_ba_graz+1.0d0)
    grazbanb = grazbanb + beta_ba_graz*tempb4
    beta_ba_grazb = (grazban-grazban*beta_ba_graz/(beta_ba_graz+1.0d0))*&
&     tempb4
