    temp2 = y(itrc)*y(inh4)
    tempb2 = growtrnh4b/temp4
    v_trnb = v_trnb + v_trmax_n*temp2*tempb2
    v_trmax_nb = v_trmax_nb + v_trn*temp2*tempb2
    tempb1 = v_trn*v_trmax_n*tempb2
    tempb3 = -(v_trn*v_trmax_n*temp2*tempb2/temp4)
    yb(inh4) = yb(inh4) + tempb3
    yb(ino3) = yb(ino3) + temp5*tempb3
    tempb4 = y(ino3)*tempb3/k_no3tr
    k_nh4trb = k_nh4trb + tempb3 + tempb4
    k_no3trb = k_no3trb - temp5*tempb4
    yb(itrc) = yb(itrc) + y(inh4)*tempb1
    yb(inh4) = yb(inh4) + y(itrc)*tempb1
    CALL POPCONTROL1B(branch)
    IF (branch .NE. 0) v_trmax_nb = 0.D0
    CALL POPCONTROL1B(branch)
    IF (branch .EQ. 0) THEN
      tempb4 = -(v_trmax_nb/(y(itrc)*(q_tr_max_n-q_tr_rdf_n)))
      yb(itrn) = yb(itrn) + tempb4
      yb(itrc) = yb(itrc) - y(itrn)*tempb4/y(itrc)
    END IF
    CALL POPCONTROL1B(branch)
    IF (branch .EQ. 0) THEN
      pc_trmaxb = 0.D0
    ELSE
      temp5 = EXP(-(rlt*a_tr))
      temp4 = alpha_tr*y(itrchl)/(y(itrc)*pc_trmax)
      tempb3 = rlt*EXP(-(rlt*temp4))*temp5*growtrcb
      tempb1 = (c1-EXP(-(rlt*temp4)))*growtrcb
      yb(itrc) = yb(itrc) + pc_trmax*temp5*tempb1
      a_trb = a_trb - rlt*EXP(-(rlt*a_tr))*y(itrc)*pc_trmax*tempb1
      alpha_trb = alpha_trb + y(itrchl)*tempb3
      yb(itrchl) = yb(itrchl) + alpha_tr*tempb3
      tempb2 = -(temp4*tempb3)
      pc_trmaxb = y(itrc)*temp5*tempb1 + y(itrc)*tempb2
      yb(itrc) = yb(itrc) + pc_trmax*tempb2
    END IF
    mu_trb = temp*pc_trmaxb
    tempb = mu_tr*pc_trmaxb
    CALL POPCONTROL1B(branch)
    IF (branch .EQ. 0) tempb = 0.D0
    CALL POPCONTROL1B(branch)
    IF (branch .EQ. 0) tempb = 0.D0
    CALL POPCONTROL1B(branch)
    IF (branch .EQ. 0) THEN
      CALL POPREAL8(temp)
      nfunc_tr_pb = tempb
    ELSE
      CALL POPREAL8(temp)
      nfunc_tr_nb = nfunc_tr_nb + tempb
      nfunc_tr_pb = 0.D0
    END IF
    tempb4 = nfunc_tr_pb/(y(itrc)*(q_tr_rdf_p-q_tr_min_p))
    yb(itrp) = yb(itrp) + tempb4
    yb(itrc) = yb(itrc) - y(itrp)*tempb4/y(itrc)
    tempb4 = nfunc_tr_nb/(y(itrc)*(q_tr_rdf_n-q_tr_min_n))
    yb(itrn) = yb(itrn) + tempb4
    yb(itrc) = yb(itrc) - y(itrn)*tempb4/y(itrc)
    tempb4 = dydttb(ispchl)/secperday
    dydttb(ispchl) = 0.D0
    growspchlb = tempb4
    grazspchlb = -tempb4
    pomspchlb = -tempb4
    tempb4 = dydttb(ispp)/secperday
    dydttb(ispp) = 0.D0
    growsppb = growsppb + tempb4
    excrsp_1pb = excrsp_1pb - tempb4
    excrsp_2pb = excrsp_2pb - tempb4
    grazsppb = grazsppb - tempb4
    pomsppb = pomsppb - tempb4
    tempb4 = dydttb(isp15n)/secperday
    dydttb(isp15n) = 0.D0
    growsp15nb = growsp15nb + tempb4
    excrsp_1_15nb = excrsp_1_15nb - tempb4
    excrsp_2_15nb = excrsp_2_15nb - tempb4
    grazsp15nb = grazsp15nb - tempb4
    pomsp15nb = pomsp15nb - tempb4
    tempb4 = dydttb(ispn)/secperday
    dydttb(ispn) = 0.D0
    growspnb = growspnb + tempb4
    excrsp_1nb = excrsp_1nb - tempb4
    excrsp_2nb = excrsp_2nb - tempb4
    grazspnb = grazspnb - tempb4
    pomspnb = pomspnb - tempb4
    tempb4 = dydttb(ispc)/secperday
    dydttb(ispc) = 0.D0
    growspcb = growspcb + tempb4
    excrsp_1cb = excrsp_1cb - tempb4
    excrsp_2cb = excrsp_2cb - tempb4
    grazspcb = grazspcb - tempb4
    pomspcb = pomspcb - tempb4
    respspb = respspb - tempb4
    tempb4 = grazspchlb/y(ispn)
    grazspnb = grazspnb + y(ispchl)*tempb4
    yb(ispchl) = yb(ispchl) + grazspn*tempb4
    yb(ispn) = yb(ispn) - grazspn*y(ispchl)*tempb4/y(ispn)
    tempb4 = grazsppb/y(ispc)
    grazspcb = grazspcb + y(ispp)*tempb4
    yb(ispp) = yb(ispp) + grazspc*tempb4
    yb(ispc) = yb(ispc) - grazspc*y(ispp)*tempb4/y(ispc)
    tempb4 = grazsp15nb/(beta_sp_graz+1.0d0)
    grazspnb = grazspnb + beta_sp_graz*tempb4
    beta_sp_grazb = (grazspn-grazspn*beta_sp_graz/(beta_sp_graz+1.0d0))*&
&     tempb4
    rspb = (1.0d0-epsilon_g/1000.0d0*factor_sp_graz)*beta_sp_grazb
    epsilon_gb = epsilon_gb - factor_sp_graz*rsp*beta_sp_grazb/1000.0d0
    factor_sp_grazb = -(epsilon_g*rsp*beta_sp_grazb/1000.0d0)
    CALL POPCONTROL1B(branch)
    IF (branch .EQ. 0) THEN
      temp5 = (-u_sp_graz+1.0d0)/u_sp_graz
      tempb4 = -(LOG(1.0d0-u_sp_graz)*factor_sp_grazb/u_sp_graz)
      u_sp_grazb = temp5*factor_sp_grazb/(1.0d0-u_sp_graz) - (temp5+1.0)&
&       *tempb4
    ELSE
      u_sp_grazb = 0.D0
    END IF
    CALL POPCONTROL1B(branch)
    IF (branch .EQ. 0) THEN
      y3b = u_sp_grazb
    ELSE
      y3b = 0.D0
    END IF
    CALL POPCONTROL1B(branch)
    IF (branch .EQ. 0) THEN
      u_sp_grazb = y3b
    ELSE
      u_sp_grazb = 0.D0
    END IF
    tempb4 = dt*u_sp_grazb/(eps+y(ispn))
    grazspnb = grazspnb + tempb4
    yb(ispn) = yb(ispn) - grazspn*tempb4/(eps+y(ispn))
    tempb4 = grazspnb/y(ispc)
    grazspcb = grazspcb + y(ispn)*tempb4
    yb(ispn) = yb(ispn) + grazspc*tempb4
    yb(ispc) = yb(ispc) - grazspc*y(ispn)*tempb4/y(ispc)
    temp4 = g_sp*g_sp/(g_ba*g_ba)
    temp3 = g_sp*g_sp/(g_un*g_un)
    temp2 = y(ispc)*y(ispc) + g_sp*g_sp + y(iunc)*y(iunc)*temp3 + y(ibac&
&     )*y(ibac)*temp4
    temp5 = y(ispc)*y(ispc)
    tempb0 = grazspcb/temp2
    mu_prtb = mu_prtb + y(iprtc)*temp5*tempb0
    yb(iprtc) = yb(iprtc) + mu_prt*temp5*tempb0
    tempb1 = -(mu_prt*y(iprtc)*temp5*tempb0/temp2)
    yb(ispc) = yb(ispc) + 2*y(ispc)*mu_prt*y(iprtc)*tempb0 + 2*y(ispc)*&
&     tempb1
    yb(iunc) = yb(iunc) + 2*y(iunc)*temp3*tempb1
    tempb2 = y(iunc)**2*tempb1/g_un**2
    yb(ibac) = yb(ibac) + 2*y(ibac)*temp4*tempb1
    tempb3 = y(ibac)**2*tempb1/g_ba**2
    g_spb = g_spb + 2*g_sp*tempb1 + 2*g_sp*tempb3 + 2*g_sp*tempb2
    g_bab = g_bab - 2*g_ba*temp4*tempb3
    g_unb = g_unb - 2*g_un*temp3*tempb2
    tempb3 = pomspchlb/y(ispn)
    pomspnb = pomspnb + y(ispchl)*tempb3
    yb(ispchl) = yb(ispchl) + pomspn*tempb3
    yb(ispn) = yb(ispn) - pomspn*y(ispchl)*tempb3/y(ispn)
    tempb3 = pomsppb/y(ispc)
    pomspcb = pomspcb + y(ispp)*tempb3
    yb(ispp) = yb(ispp) + pomspc*tempb3
    yb(ispc) = yb(ispc) - pomspc*y(ispp)*tempb3/y(ispc)
    tempb3 = pomsp15nb/(rsp+1.0d0)
    pomspnb = pomspnb + rsp*tempb3
    rspb = rspb + (pomspn-pomspn*rsp/(rsp+1.0d0))*tempb3
    tempb3 = pomspnb/y(ispc)
    pomspcb = pomspcb + y(ispn)*tempb3
    yb(ispn) = yb(ispn) + pomspc*tempb3
    yb(ispc) = yb(ispc) + 2*y(ispc)*r_pomsp*pomspcb - pomspc*y(ispn)*&
&     tempb3/y(ispc)
    r_pomspb = y(ispc)**2*pomspcb
    tempb3 = excrsp_2_15nb/(rsp+1.0d0)
    excrsp_2nb = excrsp_2nb + rsp*tempb3
    rspb = rspb + (excrsp_2n-excrsp_2n*rsp/(rsp+1.0d0))*tempb3
    r_excrsp_2b = growspc*0.25*excrsp_2cb
    growspcb = growspcb + r_excrsp_2*0.25*excrsp_2cb
    CALL POPCONTROL1B(branch)
    IF (branch .NE. 0) THEN
      min2b = 0.5*excrsp_2pb
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        excrsp_2cb = excrsp_2cb + q_sp_rdf_p*min2b
        temp1b = 0.D0
      ELSE
        yb(ispp) = yb(ispp) + temp1*0.25d0*min2b
        temp1b = y(ispp)*0.25d0*min2b
      END IF
      min1b = 0.5*excrsp_2nb
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        excrsp_2cb = excrsp_2cb + q_sp_rdf_n*min1b
        tempb = 0.D0
      ELSE
        yb(ispn) = yb(ispn) + temp*0.25d0*min1b
        tempb = y(ispn)*0.25d0*min1b
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        tempb3 = -(q_sp_rdf_p*temp1b/(q_sp_rdf_n*y(ispp)))
        yb(ispn) = yb(ispn) + tempb3
        yb(ispp) = yb(ispp) - y(ispn)*tempb3/y(ispp)
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        tempb3 = -(q_sp_rdf_n*tempb/(q_sp_rdf_p*y(ispn)))
        yb(ispp) = yb(ispp) + tempb3
        yb(ispn) = yb(ispn) - y(ispp)*tempb3/y(ispn)
      END IF
    END IF
    yb(ispc) = yb(ispc) + max1*0.5*excrsp_2cb
    max1b = y(ispc)*0.5*excrsp_2cb
    CALL POPCONTROL1B(branch)
    IF (branch .EQ. 0) THEN
      tempb = 0.D0
    ELSE
      tempb = max1b
    END IF
    CALL POPCONTROL1B(branch)
    IF (branch .EQ. 0) THEN
      CALL POPREAL8(temp)
      tempb3 = -(tempb/(q_sp_rdf_p*y(ispc)))
      yb(ispp) = yb(ispp) + tempb3
      yb(ispc) = yb(ispc) - y(ispp)*tempb3/y(ispc)
    ELSE
      CALL POPREAL8(temp)
      tempb3 = -(tempb/(q_sp_rdf_n*y(ispc)))
      yb(ispn) = yb(ispn) + tempb3
      yb(ispc) = yb(ispc) - y(ispn)*tempb3/y(ispc)
    END IF
    tempb3 = excrsp_1_15nb/(rsp+1.0d0)
    excrsp_1nb = excrsp_1nb + rsp*tempb3
    r_excrsp_1b = y(ispp)*excrsp_1pb + y(ispn)*excrsp_1nb + y(ispc)*&
&     excrsp_1cb
    yb(ispp) = yb(ispp) + r_excrsp_1*excrsp_1pb
    rspb = rspb + (excrsp_1n-excrsp_1n*rsp/(rsp+1.0d0))*tempb3
    yb(ispn) = yb(ispn) + r_excrsp_1*excrsp_1nb
    yb(ispc) = yb(ispc) + r_excrsp_1*excrsp_1cb
    r_excrsp_2b = r_excrsp_2b + growspc*0.75*excrsp_1cb
    growspcb = growspcb + r_excrsp_2*0.75*excrsp_1cb
    CALL POPCONTROL1B(branch)
    IF (branch .EQ. 0) THEN
      alpha_spb = 0.D0
      a_spb = 0.D0
    ELSE
      temp4 = EXP(-(rlt*a_sp))
      temp3 = rlt*alpha_sp*y(ispchl)
      temp2 = temp3*temp4
      tempb0 = growspchlb/temp2
      thetab = thetab + growspn*growspc*tempb0
      growspnb = growspnb + theta*growspc*tempb0
      growspcb = growspcb + theta*growspn*tempb0
      tempb1 = -(theta*growspn*growspc*tempb0/temp2)
      alpha_spb = rlt*y(ispchl)*temp4*tempb1
      yb(ispchl) = yb(ispchl) + rlt*alpha_sp*temp4*tempb1
      a_spb = -(rlt*EXP(-(rlt*a_sp))*temp3*tempb1)
    END IF
    growspno3b = growspno3b + zeta*respspb
    zetab = zetab + growspno3*respspb
    temp4 = v_spp*v_spmax_p/(y(ipo4)+k_po4sp)
    tempb3 = y(ispc)*y(ipo4)*growsppb/(y(ipo4)+k_po4sp)
    yb(ispc) = yb(ispc) + y(ipo4)*temp4*growsppb
    v_sppb = v_spmax_p*tempb3
    v_spmax_pb = v_spp*tempb3
    tempb2 = -(temp4*tempb3)
    yb(ipo4) = yb(ipo4) + y(ispc)*temp4*growsppb + tempb2
    k_po4spb = tempb2
    CALL POPCONTROL1B(branch)
    IF (branch .NE. 0) v_spmax_pb = 0.D0
    CALL POPCONTROL1B(branch)
    IF (branch .EQ. 0) THEN
      tempb3 = -(v_spmax_pb/(y(ispc)*(q_sp_max_p-q_sp_rdf_p)))
      yb(ispp) = yb(ispp) + tempb3
      yb(ispc) = yb(ispc) - y(ispp)*tempb3/y(ispc)
    END IF
    growsp15nh4b = growsp15nh4b + growsp15nb
    growsp15no3b = growsp15no3b + growsp15nb
    tempb3 = growsp15no3b/(beta_no3_sp+1.0d0)
    growspno3b = growspno3b + beta_no3_sp*tempb3
    beta_no3_spb = (growspno3-growspno3*beta_no3_sp/(beta_no3_sp+1.0d0))&
&     *tempb3
    rno3b = rno3b + (1.0d0-epsilon_ano3/1000.0d0*factor_no3_sp)*&
&     beta_no3_spb
    epsilon_ano3b = epsilon_ano3b - factor_no3_sp*rno3*beta_no3_spb/&
&     1000.0d0
    factor_no3_spb = -(epsilon_ano3*rno3*beta_no3_spb/1000.0d0)
    CALL POPCONTROL2B(branch)
    IF (branch .EQ. 0) THEN
      temp4 = (-u_no3_sp+1.0d0)/u_no3_sp
      tempb3 = -(LOG(1.0d0-u_no3_sp)*factor_no3_spb/u_no3_sp)
      u_no3_spb = temp4*factor_no3_spb/(1.0d0-u_no3_sp) - (temp4+1.0)*&
&       tempb3
    ELSE IF (branch .EQ. 1) THEN
      u_no3_spb = 0.D0
    ELSE
      u_no3_spb = 0.D0
    END IF
    CALL POPCONTROL1B(branch)
    IF (branch .EQ. 0) THEN
      y2b = u_no3_spb
    ELSE
      y2b = 0.D0
    END IF
    CALL POPCONTROL1B(branch)
    IF (branch .EQ. 0) THEN
      u_no3_spb = y2b
    ELSE
      u_no3_spb = 0.D0
    END IF
    tempb3 = dt*u_no3_spb/(eps+y(ino3))
    growspno3b = growspno3b + tempb3
    yb(ino3) = yb(ino3) - growspno3*tempb3/(eps+y(ino3))
    tempb3 = growsp15nh4b/(beta_nh4_sp+1.0d0)
    growspnh4b = growspnh4b + beta_nh4_sp*tempb3
    beta_nh4_spb = (growspnh4-growspnh4*beta_nh4_sp/(beta_nh4_sp+1.0d0))&
&     *tempb3
    rnh4b = rnh4b + (1.0d0-epsilon_anh4/1000.0d0*factor_nh4_sp)*&
&     beta_nh4_spb
    epsilon_anh4b = epsilon_anh4b - factor_nh4_sp*rnh4*beta_nh4_spb/&
&     1000.0d0
    factor_nh4_spb = -(epsilon_anh4*rnh4*beta_nh4_spb/1000.0d0)
    CALL POPCONTROL2B(branch)
    IF (branch .EQ. 0) THEN
      temp4 = (-u_nh4_sp+1.0d0)/u_nh4_sp
      tempb3 = -(LOG(1.0d0-u_nh4_sp)*factor_nh4_spb/u_nh4_sp)
      u_nh4_spb = temp4*factor_nh4_spb/(1.0d0-u_nh4_sp) - (temp4+1.0)*&
&       tempb3
    ELSE IF (branch .EQ. 1) THEN
      u_nh4_spb = 0.D0
    ELSE
      u_nh4_spb = 0.D0
    END IF
    CALL POPCONTROL1B(branch)
    IF (branch .EQ. 0) THEN
      y1b = u_nh4_spb
    ELSE
      y1b = 0.D0
    END IF
    CALL POPCONTROL1B(branch)
    IF (branch .EQ. 0) THEN
      u_nh4_spb = y1b
    ELSE
      u_nh4_spb = 0.D0
    END IF
    tempb3 = dt*u_nh4_spb/(eps+y(inh4))
    growspnh4b = growspnh4b + tempb3 + growspnb
    yb(inh4) = yb(inh4) - growspnh4*tempb3/(eps+y(inh4))
    growspno3b = growspno3b + growspnb
    temp4 = k_no3sp/k_nh4sp
    temp3 = y(ino3) + k_no3sp + y(inh4)*temp4
    temp0 = y(ispc)*y(ino3)
    tempb1 = growspno3b/temp3
    v_spnb = v_spmax_n*temp0*tempb1
    v_spmax_nb = v_spn*temp0*tempb1
    tempb0 = v_spn*v_spmax_n*tempb1
    tempb2 = -(v_spn*v_spmax_n*temp0*tempb1/temp3)
    yb(ino3) = yb(ino3) + tempb2
    yb(inh4) = yb(inh4) + temp4*tempb2
    tempb3 = y(inh4)*tempb2/k_nh4sp
    k_no3spb = tempb2 + tempb3
    k_nh4spb = -(temp4*tempb3)
    yb(ispc) = yb(ispc) + y(ino3)*tempb0
    yb(ino3) = yb(ino3) + y(ispc)*tempb0
    temp4 = k_nh4sp/k_no3sp
    temp3 = y(inh4) + k_nh4sp + y(ino3)*temp4
    temp0 = y(ispc)*y(inh4)
    tempb1 = growspnh4b/temp3
    v_spnb = v_spnb + v_spmax_n*temp0*tempb1
    v_spmax_nb = v_spmax_nb + v_spn*temp0*tempb1
    tempb0 = v_spn*v_spmax_n*tempb1
    tempb2 = -(v_spn*v_spmax_n*temp0*tempb1/temp3)
    yb(inh4) = yb(inh4) + tempb2
    yb(ino3) = yb(ino3) + temp4*tempb2
    tempb3 = y(ino3)*tempb2/k_no3sp
    k_nh4spb = k_nh4spb + tempb2 + tempb3
    k_no3spb = k_no3spb - temp4*tempb3
    yb(ispc) = yb(ispc) + y(inh4)*tempb0
    yb(inh4) = yb(inh4) + y(ispc)*tempb0
    CALL POPCONTROL1B(branch)
    IF (branch .NE. 0) v_spmax_nb = 0.D0
    CALL POPCONTROL1B(branch)
    IF (branch .EQ. 0) THEN
      tempb3 = -(v_spmax_nb/(y(ispc)*(q_sp_max_n-q_sp_rdf_n)))
      yb(ispn) = yb(ispn) + tempb3
      yb(ispc) = yb(ispc) - y(ispn)*tempb3/y(ispc)
    END IF
    CALL POPCONTROL1B(branch)
    IF (branch .EQ. 0) THEN
      pc_spmaxb = 0.D0
    ELSE
      temp0 = EXP(-(rlt*a_sp))
      temp2 = alpha_sp*y(ispchl)/(y(ispc)*pc_spmax)
      tempb1 = rlt*EXP(-(rlt*temp2))*temp0*growspcb
      tempb3 = (c1-EXP(-(rlt*temp2)))*growspcb
      yb(ispc) = yb(ispc) + pc_spmax*temp0*tempb3
      a_spb = a_spb - rlt*EXP(-(rlt*a_sp))*y(ispc)*pc_spmax*tempb3
      alpha_spb = alpha_spb + y(ispchl)*tempb1
      yb(ispchl) = yb(ispchl) + alpha_sp*tempb1
      tempb2 = -(temp2*tempb1)
      pc_spmaxb = y(ispc)*temp0*tempb3 + y(ispc)*tempb2
      yb(ispc) = yb(ispc) + pc_spmax*tempb2
    END IF
    mu_spb = temp*pc_spmaxb
    tempb = mu_sp*pc_spmaxb
    CALL POPCONTROL1B(branch)
    IF (branch .EQ. 0) tempb = 0.D0
    CALL POPCONTROL1B(branch)
    IF (branch .EQ. 0) tempb = 0.D0
    CALL POPCONTROL1B(branch)
    IF (branch .EQ. 0) THEN
      nfunc_sp_pb = tempb
      nfunc_sp_nb = 0.D0
    ELSE
      nfunc_sp_nb = tempb
      nfunc_sp_pb = 0.D0
    END IF
    tempb0 = nfunc_sp_pb/(y(ispc)*(q_sp_rdf_p-q_sp_min_p))
    yb(ispp) = yb(ispp) + tempb0
    yb(ispc) = yb(ispc) - y(ispp)*tempb0/y(ispc)
    tempb0 = nfunc_sp_nb/(y(ispc)*(q_sp_rdf_n-q_sp_min_n))
    yb(ispn) = yb(ispn) + tempb0
    yb(ispc) = yb(ispc) - y(ispn)*tempb0/y(ispc)
    temp0 = eps + y(ino3) - y(i15no3)
    yb(i15no3) = yb(i15no3) + rno3b/temp0
    tempb0 = -(y(i15no3)*rno3b/temp0**2)
    yb(ino3) = yb(ino3) + tempb0
    yb(i15no3) = yb(i15no3) - tempb0
    temp0 = eps + y(inh4) - y(i15nh4)
    yb(i15nh4) = yb(i15nh4) + rnh4b/temp0
    tempb0 = -(y(i15nh4)*rnh4b/temp0**2)
    yb(inh4) = yb(inh4) + tempb0
    yb(i15nh4) = yb(i15nh4) - tempb0
    temp0 = eps + y(ildomn) - y(ildom15n)
    yb(ildom15n) = yb(ildom15n) + rldomb/temp0
    tempb0 = -(y(ildom15n)*rldomb/temp0**2)
    yb(ildomn) = yb(ildomn) + tempb0
    yb(ildom15n) = yb(ildom15n) - tempb0
    temp0 = eps + y(idetn) - y(idet15n)
    yb(idet15n) = yb(idet15n) + rdetb/temp0
    tempb0 = -(y(idet15n)*rdetb/temp0**2)
    yb(idetn) = yb(idetn) + tempb0
    yb(idet15n) = yb(idet15n) - tempb0
    temp0 = eps + y(imzn) - y(imz15n)
    yb(imz15n) = yb(imz15n) + rmzb/temp0
    tempb0 = -(y(imz15n)*rmzb/temp0**2)
    yb(imzn) = yb(imzn) + tempb0
    yb(imz15n) = yb(imz15n) - tempb0
    temp0 = eps + y(iprtn) - y(iprt15n)
    yb(iprt15n) = yb(iprt15n) + rprtb/temp0
    tempb0 = -(y(iprt15n)*rprtb/temp0**2)
    yb(iprtn) = yb(iprtn) + tempb0
    yb(iprt15n) = yb(iprt15n) - tempb0
    temp0 = eps + y(iban) - y(iba15n)
    yb(iba15n) = yb(iba15n) + rbab/temp0
    tempb0 = -(y(iba15n)*rbab/temp0**2)
    yb(iban) = yb(iban) + tempb0
    yb(iba15n) = yb(iba15n) - tempb0
    temp0 = eps + y(iunn) - y(iun15n)
    yb(iun15n) = yb(iun15n) + runb/temp0
    tempb0 = -(y(iun15n)*runb/temp0**2)
    yb(iunn) = yb(iunn) + tempb0
    yb(iun15n) = yb(iun15n) - tempb0
    temp0 = eps + y(iddan) - y(idda15n)
    yb(idda15n) = yb(idda15n) + rddab/temp0
    tempb0 = -(y(idda15n)*rddab/temp0**2)
    yb(iddan) = yb(iddan) + tempb0
    yb(idda15n) = yb(idda15n) - tempb0
    temp0 = eps + y(itrn) - y(itr15n)
    yb(itr15n) = yb(itr15n) + rtrb/temp0
    tempb0 = -(y(itr15n)*rtrb/temp0**2)
    yb(itrn) = yb(itrn) + tempb0
    yb(itr15n) = yb(itr15n) - tempb0
    temp0 = eps + y(ispn) - y(isp15n)
    yb(isp15n) = yb(isp15n) + rspb/temp0
    tempb0 = -(y(isp15n)*rspb/temp0**2)
    yb(ispn) = yb(ispn) + tempb0
    yb(isp15n) = yb(isp15n) - tempb0
    CALL POPREAL8(r_mzresp_1)
    CALL POPREAL8(mu_mz)
    CALL POPREAL8(r_prtresp_1)
    CALL POPREAL8(r_baresp_1)
    CALL POPREAL8(mu_prt)
    CALL POPREAL8(mu_ba)
    CALL POPREAL8(v_unp)
    CALL POPREAL8(v_unn)
    CALL POPREAL8(mu_un)
    CALL POPREAL8(v_ddap)
    CALL POPREAL8(v_ddan)
    CALL POPREAL8(mu_dda)
    CALL POPREAL8(v_trp)
    CALL POPREAL8(v_trn)
    CALL POPREAL8(mu_tr)
    CALL POPREAL8(v_spp)
    CALL POPREAL8(v_spn)
    CALL POPREAL8(mu_sp)
    tfuncb = tfuncb + r_mzresp_1*r_mzresp_1b + mu_mz*mu_mzb + &
&     r_prtresp_1*r_prtresp_1b + r_baresp_1*r_baresp_1b + mu_prt*mu_prtb&
&     + mu_ba*mu_bab + v_unp*v_unpb + v_unn*v_unnb + mu_un*mu_unb + &
&     v_ddap*v_ddapb + v_ddan*v_ddanb + mu_dda*mu_ddab + v_trp*v_trpb + &
&     v_trn*v_trnb + mu_tr*mu_trb + v_spp*v_sppb + v_spn*v_spnb + mu_sp*&
&     mu_spb
    r_mzresp_1b = tfunc*r_mzresp_1b
    mu_mzb = tfunc*mu_mzb
    r_prtresp_1b = tfunc*r_prtresp_1b
    r_baresp_1b = tfunc*r_baresp_1b
    mu_prtb = tfunc*mu_prtb
    mu_bab = tfunc*mu_bab
    v_unpb = tfunc*v_unpb
    v_unnb = tfunc*v_unnb
    mu_unb = tfunc*mu_unb
    v_ddapb = tfunc*v_ddapb
    v_ddanb = tfunc*v_ddanb
    mu_ddab = tfunc*mu_ddab
    v_trpb = tfunc*v_trpb
    v_trnb = tfunc*v_trnb
    mu_trb = tfunc*mu_trb
    v_sppb = tfunc*v_sppb + v_unpb
    v_spnb = tfunc*v_spnb + v_unnb
    mu_spb = tfunc*mu_spb
    temp0 = 1.0/(result1+273.15) - 1.0/(tref+273.15)
    aeb = -(temp0*EXP(-(temp0*ae))*tfuncb)
    a_spb = a_spb + a_unb
    g_spb = g_spb + g_unb
    r_pomspb = r_pomspb + r_pomunb
    r_excrsp_2b = r_excrsp_2b + r_excrun_2b
    r_excrtr_nb = r_excrtr_nb + r_excrun_nb
    r_excrsp_1b = r_excrsp_1b + r_excrun_1b
    k_po4spb = k_po4spb + k_po4unb
    k_no3spb = k_no3spb + k_no3unb
    k_nh4spb = k_nh4spb + k_nh4unb
    bioparamsb = 0.D0
    bioparamsb(iepsilon_exnh4) = bioparamsb(iepsilon_exnh4) + &
&     epsilon_exnh4b
    bioparamsb(iepsilon_g) = bioparamsb(iepsilon_g) + epsilon_gb
    bioparamsb(iepsilon_nf) = bioparamsb(iepsilon_nf) + epsilon_nfb
    bioparamsb(iepsilon_remin) = bioparamsb(iepsilon_remin) + &
&     epsilon_reminb
    bioparamsb(iepsilon_nitrf) = bioparamsb(iepsilon_nitrf) + &
&     epsilon_nitrfb
    bioparamsb(iepsilon_ano3) = bioparamsb(iepsilon_ano3) + &
&     epsilon_ano3b
    bioparamsb(iepsilon_anh4) = bioparamsb(iepsilon_anh4) + &
&     epsilon_anh4b
    bioparamsb(ir_std) = bioparamsb(ir_std) + r_stdb
    bioparamsb(iremin) = bioparamsb(iremin) + reminb
    bioparamsb(iwnsvo) = bioparamsb(iwnsvo) + wnsvob
    bioparamsb(iremin_prf_p) = bioparamsb(iremin_prf_p) + remin_prf_pb
    bioparamsb(iremin_prf_n) = bioparamsb(iremin_prf_n) + remin_prf_nb
    bioparamsb(ir_nitrf) = bioparamsb(ir_nitrf) + r_nitrfb
    bioparamsb(iq_pom_p) = bioparamsb(iq_pom_p) + q_pom_pb
    bioparamsb(iq_pom_n) = bioparamsb(iq_pom_n) + q_pom_nb
    bioparamsb(iq_refrdom_p) = bioparamsb(iq_refrdom_p) + q_refrdom_pb
    bioparamsb(iq_refrdom_n) = bioparamsb(iq_refrdom_n) + q_refrdom_nb
    bioparamsb(if_hzpom) = bioparamsb(if_hzpom) + f_hzpomb
    bioparamsb(if_hzsdom) = bioparamsb(if_hzsdom) + f_hzsdomb
    bioparamsb(ir_mzremv) = bioparamsb(ir_mzremv) + r_mzremvb
    bioparamsb(ir_mzpom) = bioparamsb(ir_mzpom) + r_mzpomb
    bioparamsb(ir_mzremi) = bioparamsb(ir_mzremi) + r_mzremib
    bioparamsb(ir_mzadju) = bioparamsb(ir_mzadju) + r_mzadjub
    bioparamsb(ir_mzresp_2) = bioparamsb(ir_mzresp_2) + r_mzresp_2b
    bioparamsb(ir_mzresp_1) = bioparamsb(ir_mzresp_1) + r_mzresp_1b
    bioparamsb(if_exmzldom) = bioparamsb(if_exmzldom) + f_exmzldomb
    bioparamsb(ir_mzex) = bioparamsb(ir_mzex) + r_mzexb
    bioparamsb(ig_dda) = bioparamsb(ig_dda) + g_ddab
    bioparamsb(ig_tr) = bioparamsb(ig_tr) + g_trb
    bioparamsb(ig_prt) = bioparamsb(ig_prt) + g_prtb
    bioparamsb(imu_mz) = bioparamsb(imu_mz) + mu_mzb
    bioparamsb(ir_pomprt) = bioparamsb(ir_pomprt) + r_pomprtb
    bioparamsb(ir_prtremi) = bioparamsb(ir_prtremi) + r_prtremib
    bioparamsb(ir_prtadju) = bioparamsb(ir_prtadju) + r_prtadjub
    bioparamsb(ir_prtresp_2) = bioparamsb(ir_prtresp_2) + r_prtresp_2b
    bioparamsb(ir_prtresp_1) = bioparamsb(ir_prtresp_1) + r_prtresp_1b
    bioparamsb(if_exprtldom) = bioparamsb(if_exprtldom) + f_exprtldomb
    bioparamsb(ir_prtex) = bioparamsb(ir_prtex) + r_prtexb
    bioparamsb(ig_ba) = bioparamsb(ig_ba) + g_bab
    bioparamsb(ig_sp) = bioparamsb(ig_sp) + g_spb
    bioparamsb(imu_prt) = bioparamsb(imu_prt) + mu_prtb
    bioparamsb(ir_bamort) = bioparamsb(ir_bamort) + r_bamortb
    bioparamsb(ir_baresp_max) = bioparamsb(ir_baresp_max) + &
&     r_baresp_maxb
    bioparamsb(ir_baresp_min) = bioparamsb(ir_baresp_min) + &
&     r_baresp_minb
    bioparamsb(ir_baresp_1) = bioparamsb(ir_baresp_1) + r_baresp_1b
    bioparamsb(if_baslct) = bioparamsb(if_baslct) + f_baslctb
    bioparamsb(ir_barefr) = bioparamsb(ir_barefr) + r_barefrb
    bioparamsb(ir_baremi) = bioparamsb(ir_baremi) + r_baremib
    bioparamsb(ir_baadju) = bioparamsb(ir_baadju) + r_baadjub
    bioparamsb(ib_baresp) = bioparamsb(ib_baresp) + b_barespb
    bioparamsb(imu_ba) = bioparamsb(imu_ba) + mu_bab
    bioparamsb(ir_sdom) = bioparamsb(ir_sdom) + r_sdomb
    bioparamsb(ik_dom) = bioparamsb(ik_dom) + k_domb
    bioparamsb(ialpha_un) = bioparamsb(ialpha_un) + alpha_unb
    bioparamsb(imu_un) = bioparamsb(imu_un) + mu_unb
    bioparamsb(ir_pomdda) = bioparamsb(ir_pomdda) + r_pomddab
    bioparamsb(ir_excrdda_2) = bioparamsb(ir_excrdda_2) + r_excrdda_2b
    bioparamsb(ir_excrdda_n) = bioparamsb(ir_excrdda_n) + r_excrdda_nb
    bioparamsb(ir_excrdda_1) = bioparamsb(ir_excrdda_1) + r_excrdda_1b
    bioparamsb(izeta_nf_dda) = bioparamsb(izeta_nf_dda) + zeta_nf_ddab
    bioparamsb(imu_pickddapo4) = bioparamsb(imu_pickddapo4) + &
&     mu_pickddapo4b
    bioparamsb(ik_po4dda) = bioparamsb(ik_po4dda) + k_po4ddab
    bioparamsb(iv_ddap) = bioparamsb(iv_ddap) + v_ddapb
    bioparamsb(ik_no3dda) = bioparamsb(ik_no3dda) + k_no3ddab
    bioparamsb(ik_nh4dda) = bioparamsb(ik_nh4dda) + k_nh4ddab
    bioparamsb(iv_ddan) = bioparamsb(iv_ddan) + v_ddanb
    bioparamsb(ia_dda) = bioparamsb(ia_dda) + a_ddab
    bioparamsb(ialpha_dda) = bioparamsb(ialpha_dda) + alpha_ddab
    bioparamsb(imu_dda) = bioparamsb(imu_dda) + mu_ddab
    bioparamsb(ir_pomtr) = bioparamsb(ir_pomtr) + r_pomtrb
    bioparamsb(ir_excrtr_2) = bioparamsb(ir_excrtr_2) + r_excrtr_2b
    bioparamsb(ir_excrtr_n) = bioparamsb(ir_excrtr_n) + r_excrtr_nb
    bioparamsb(ir_excrtr_1) = bioparamsb(ir_excrtr_1) + r_excrtr_1b
    bioparamsb(izeta_nf) = bioparamsb(izeta_nf) + zeta_nfb
    bioparamsb(imu_picktrpo4) = bioparamsb(imu_picktrpo4) + &
&     mu_picktrpo4b
    bioparamsb(ik_po4tr) = bioparamsb(ik_po4tr) + k_po4trb
    bioparamsb(iv_trp) = bioparamsb(iv_trp) + v_trpb
    bioparamsb(ik_no3tr) = bioparamsb(ik_no3tr) + k_no3trb
    bioparamsb(ik_nh4tr) = bioparamsb(ik_nh4tr) + k_nh4trb
    bioparamsb(iv_trn) = bioparamsb(iv_trn) + v_trnb
    bioparamsb(ia_tr) = bioparamsb(ia_tr) + a_trb
    bioparamsb(ialpha_tr) = bioparamsb(ialpha_tr) + alpha_trb
    bioparamsb(imu_tr) = bioparamsb(imu_tr) + mu_trb
    bioparamsb(ir_pomsp) = bioparamsb(ir_pomsp) + r_pomspb
    bioparamsb(ir_excrsp_2) = bioparamsb(ir_excrsp_2) + r_excrsp_2b
    bioparamsb(ir_excrsp_1) = bioparamsb(ir_excrsp_1) + r_excrsp_1b
    bioparamsb(itheta) = bioparamsb(itheta) + thetab
    bioparamsb(izeta) = bioparamsb(izeta) + zetab
    bioparamsb(ik_po4sp) = bioparamsb(ik_po4sp) + k_po4spb
    bioparamsb(iv_spp) = bioparamsb(iv_spp) + v_sppb
    bioparamsb(ik_no3sp) = bioparamsb(ik_no3sp) + k_no3spb
    bioparamsb(ik_nh4sp) = bioparamsb(ik_nh4sp) + k_nh4spb
    bioparamsb(iv_spn) = bioparamsb(iv_spn) + v_spnb
    bioparamsb(ia_sp) = bioparamsb(ia_sp) + a_spb
    bioparamsb(ialpha_sp) = bioparamsb(ialpha_sp) + alpha_spb
    bioparamsb(imu_sp) = bioparamsb(imu_sp) + mu_spb
    bioparamsb(iae) = bioparamsb(iae) + aeb
  END SUBROUTINE DERIVS_B

   SUBROUTINE DERIVS(y, dydtt, dydtt_diag, istep, iz, bioparams)
    USE CONST, ONLY : c0, c1, secperday
