&   ik_nh4sp, ik_no3sp, iv_spp, ik_po4sp, izeta, itheta, ir_excrsp_1, &
&   ir_excrsp_2, ir_pomsp, imu_tr, ialpha_tr, ia_tr, iv_trn, ik_nh4tr, &
&   ik_no3tr, iv_trp, ik_po4tr, imu_picktrpo4, izeta_nf, ir_excrtr_1, &
&   ir_excrtr_n, ir_excrtr_2, ir_pomtr, imu_dda, ialpha_dda, ia_dda, &
