&   ir_pomprt, imu_mz, ig_prt, ig_tr, ig_dda, ir_mzex, if_exmzldom, &
&   ir_mzresp_1, ir_mzresp_2, ir_mzadju, ir_mzremi, ir_mzpom, ir_mzremv,&
