&   ir_innh4
    USE ECO_PARAMS, ONLY : numstatevar, numdiagvar
    USE ECO_PARAMS, ONLY : ispc, ispn, ispp, itrc, itrn, itrp, iddac, &
&   iddan, iddap, iunc, iunn, iunp, ibac, iban, ibap, iprtc, iprtn, &
