!irefrMZc, irefrMZn, irefrMZp, &
    USE ECO_PARAMS, ONLY : ipp, iprbac, igrowspc, igrowspnh4, igrowspno3&
&   , igrowspn, igrowspp, iexcrsp_1c, iexcrsp_1n, iexcrsp_1p, iexcrsp_2c&
