&   iexcrun_2p, ipomunc, ipomunn, ipomunp, igrazunc, igrazunn, igrazunp,&
&   igrowbaldoc, igrowbaldon, igrowbaldop, igrowbasdoc, igrowbasdon, &
&   igrowbasdop, igrowbanh4, igrowbano3, igrowbapo4, igrowbac, igrowban,&
&   igrowbap, irespba, irefrbac, irefrban, irefrbap, iexcrbac, iexcrban,&
&   iexcrbap, iremiban, iremibap, igrazbac, igrazban, igrazbap, imortbac&
&   , imortban, imortbap, ifluxbanh4, ifluxbapo4, igrowprtc, igrowprtn, &
&   igrowprtp, irespprt, iexcrprtldomc, iexcrprtldomn, iexcrprtldomp, &
&   iexcrprtsdomc, iexcrprtsdomn, iexcrprtsdomp, iexcrprtsdom2c, &
&   iexcrprtsdom2n, iexcrprtsdom2p, iremiprtn, iremiprtp, ipomprtc, &
&   ipomprtn, ipomprtp, igrazprtc, igrazprtn, igrazprtp, igrowmzc, &
&   igrowmzn, igrowmzp, irespmz, iexcrmzldomc, iexcrmzldomn, &
&   iexcrmzldomp, iexcrmzsdomc, iexcrmzsdomn, iexcrmzsdomp, &
&   iexcrmzsdom2c, iexcrmzsdom2n, iexcrmzsdom2p, iremimzn, iremimzp, &
&   ipommzc, ipommzn, ipommzp, iremvmzc, iremvmzn, iremvmzp, ipomhzc, &
&   ipomhzn, ipomhzp, iexcrhzsdomc, iexcrhzsdomn, iexcrhzsdomp, iremihzn&
&   , iremihzp, idisdetc, idisdetn, idisdetp, initrf, iexportc, iexportn&
&   , iexportp, irespsp, iresptr, irespdda, irespun
! 15N 
    USE ECO_PARAMS, ONLY : isp15n, itr15n, idda15n, iun15n, iba15n, &
&   iprt15n, imz15n, ildom15n, isdom15n, idet15n, i15nh4, i15no3
