! Optimal protozoa [C, N, P]: C ratio
    q_prt_n = 0.2d0
    q_prt_p = 0.022d0
! Optimal metazoa [C, N, P]: C ratio
    q_mz_n = 0.2d0
    q_mz_p = 0.008d0
    a_un = a_sp
! Reference Temperature for Function of Temperatue Effects
    tref = 25.d0
! Temperature Effects
    result1 = TDAT(iz, istep)
    tfunc = EXP(-(ae*(1/(result1+273.15)-1/(tref+273.15))))
    mu_sp = mu_sp*tfunc
    v_spn = v_spn*tfunc
    v_spp = v_spp*tfunc
    mu_tr = mu_tr*tfunc
    v_trn = v_trn*tfunc
    v_trp = v_trp*tfunc
    mu_dda = mu_dda*tfunc
    v_ddan = v_ddan*tfunc
    v_ddap = v_ddap*tfunc
    mu_un = mu_un*tfunc
    v_unn = v_unn*tfunc
    v_unp = v_unp*tfunc
    mu_ba = mu_ba*tfunc
    mu_prt = mu_prt*tfunc
    r_baresp_1 = r_baresp_1*tfunc
    r_prtresp_1 = r_prtresp_1*tfunc
    mu_mz = mu_mz*tfunc
    r_mzresp_1 = r_mzresp_1*tfunc
!  15N/N 
   rsp  = y(isp15n)  / max(y(ispn)  - y(isp15n) + eps, 1.0d-20)
   rtr  = y(itr15n)  / max(y(itrn)  - y(itr15n) + eps, 1.0d-20)
   rdda = y(idda15n) / max(y(iddan) - y(idda15n) + eps, 1.0d-20)
   run  = y(iun15n)  / max(y(iunn)  - y(iun15n) + eps, 1.0d-20)
   rba  = y(iba15n)  / max(y(iban)  - y(iba15n) + eps, 1.0d-20)
   rprt = y(iprt15n) / max(y(iprtn) - y(iprt15n) + eps, 1.0d-20)
   rmz  = y(imz15n)  / max(y(imzn)  - y(imz15n) + eps, 1.0d-20)
   rdet = y(idet15n) / max(y(idetn) - y(idet15n) + eps, 1.0d-20)
   rldom= y(ildom15n)/ max(y(ildomn)- y(ildom15n) + eps, 1.0d-20)
   rnh4 = y(i15nh4) / max(y(inh4)  - y(i15nh4) + eps, 1.0d-20)
   rno3 = y(i15no3) / max(y(ino3)  - y(i15no3) + eps, 1.0d-20)
!-----------------------------------------------------------------------
!      Microphytoplankton Processes
!-----------------------------------------------------------------------
! Nutrient quota Limitation
    nfunc_sp_n = (y(ispn)/y(ispc)-q_sp_min_n)/(q_sp_rdf_n-q_sp_min_n)
    nfunc_sp_p = (y(ispp)/y(ispc)-q_sp_min_p)/(q_sp_rdf_p-q_sp_min_p)
    IF (nfunc_sp_n .GT. nfunc_sp_p) THEN
      temp = nfunc_sp_p
    ELSE
      temp = nfunc_sp_n
    END IF
    IF (temp .GT. c1) THEN
      temp = c1
    ELSE
      temp = temp
    END IF
    IF (temp .LT. c0) THEN
      temp = c0
    ELSE
      temp = temp
    END IF
    pc_spmax = mu_sp*temp
! Light Limitation
    IF (pc_spmax .GT. c0 .AND. y(ispc) .GT. c0) THEN
      growspc = y(ispc)*pc_spmax*(c1-EXP(-(alpha_sp*y(ispchl)/y(ispc)*&
&       rlt/pc_spmax)))*EXP(-(a_sp*rlt))
    ELSE
      growspc = c0
    END IF
    IF (c0 .LT. (q_sp_max_n-y(ispn)/y(ispc))/(q_sp_max_n-q_sp_rdf_n)) &
&   THEN
      v_spmax_n = (q_sp_max_n-y(ispn)/y(ispc))/(q_sp_max_n-q_sp_rdf_n)
    ELSE
      v_spmax_n = c0
    END IF
    IF (c1 .GT. v_spmax_n) THEN
      v_spmax_n = v_spmax_n
    ELSE
      v_spmax_n = c1
    END IF
    growspnh4 = y(ispc)*v_spn*v_spmax_n*y(inh4)/(y(inh4)+k_nh4sp+y(ino3)&
&     *k_nh4sp/k_no3sp)
    growspno3 = y(ispc)*v_spn*v_spmax_n*y(ino3)/(y(ino3)+k_no3sp+y(inh4)&
&     *k_no3sp/k_nh4sp)
    growspn = growspnh4 + growspno3
! 15N
! dt = 1.0d0 / 24.0d0
    dt = 3600.0d0
!=======================================================================
! mmol/m3  mu_mol/L
!=======================================================================
!double precision :: :: smooth_factor
! 0.01
    no3_limit = 0.01d0
! 0.001
    nh4_limit = 0.001d0
!--------------------------------------------------------------------
! SP NH4 assimilation
!--------------------------------------------------------------------
    u_nh4_sp = growspnh4*dt/(y(inh4)+eps)
    IF (0.9d0 .GT. u_nh4_sp) THEN
      y1 = u_nh4_sp
    ELSE
      y1 = 0.9d0
    END IF
    IF (0.0d0 .LT. y1) THEN
      u_nh4_sp = y1
    ELSE
      u_nh4_sp = 0.0d0
    END IF
    IF (y(inh4) .LT. nh4_limit) THEN
!B
      factor_nh4_sp = 0.0d0
    ELSE IF (u_nh4_sp .LT. 1.0d-8) THEN
!A
      factor_nh4_sp = 1.0d0
    ELSE
!  Rayleigh 
      factor_nh4_sp = -((1.0d0-u_nh4_sp)/u_nh4_sp*LOG(1.0d0-u_nh4_sp))
    END IF
!  SP NH4 beta  
    beta_nh4_sp = rnh4*(1.0d0-epsilon_anh4/1000.0d0*factor_nh4_sp)
!  SP  15N 
    growsp15nh4 = growspnh4*(beta_nh4_sp/(1.0d0+beta_nh4_sp))
!--------------------------------------------------------------------
! SP NO3 assimilation
!--------------------------------------------------------------------
    u_no3_sp = growspno3*dt/(y(ino3)+eps)
    IF (0.9d0 .GT. u_no3_sp) THEN
      y2 = u_no3_sp
    ELSE
      y2 = 0.9d0
    END IF
    IF (0.0d0 .LT. y2) THEN
      u_no3_sp = y2
    ELSE
      u_no3_sp = 0.0d0
    END IF
    IF (y(ino3) .LT. no3_limit) THEN
!B
      factor_no3_sp = 0.0d0
    ELSE IF (u_no3_sp .LT. 1.0d-8) THEN
!A
      factor_no3_sp = 1.0d0
    ELSE
      factor_no3_sp = -((1.0d0-u_no3_sp)/u_no3_sp*LOG(1.0d0-u_no3_sp))
    END IF
! SP NO3 beta  
    beta_no3_sp = rno3*(1.0d0-epsilon_ano3/1000.0d0*factor_no3_sp)
!  SP  15N 
    growsp15no3 = growspno3*(beta_no3_sp/(1.0d0+beta_no3_sp))
! DIN15N
    growsp15n = growsp15nh4 + growsp15no3
    IF (c0 .LT. (q_sp_max_p-y(ispp)/y(ispc))/(q_sp_max_p-q_sp_rdf_p)) &
&   THEN
      v_spmax_p = (q_sp_max_p-y(ispp)/y(ispc))/(q_sp_max_p-q_sp_rdf_p)
    ELSE
      v_spmax_p = c0
    END IF
    IF (c1 .GT. v_spmax_p) THEN
      v_spmax_p = v_spmax_p
    ELSE
      v_spmax_p = c1
    END IF
    growspp = y(ispc)*v_spp*v_spmax_p*y(ipo4)/(y(ipo4)+k_po4sp)
    respsp = growspno3*zeta
! Chlorophyll
    IF (rlt .GT. c0) THEN
      growspchl = theta*growspn*growspc/(alpha_sp*y(ispchl)*rlt*EXP(-(&
&       a_sp*rlt)))
    ELSE
      growspchl = c0
    END IF
! SP excretion (could be also considered as mortality)
! Passive
    excrsp_1c = r_excrsp_1*y(ispc) + r_excrsp_2*growspc*0.75
    excrsp_1n = r_excrsp_1*y(ispn)
! 15N  1
    excrsp_1_15n = excrsp_1n*(rsp/(1.0d0+rsp))
    excrsp_1p = r_excrsp_1*y(ispp)
    IF (c1 - y(ispn)/y(ispc)/q_sp_rdf_n .LT. c1 - y(ispp)/y(ispc)/&
&       q_sp_rdf_p) THEN
      temp = c1 - y(ispp)/y(ispc)/q_sp_rdf_p
    ELSE
      temp = c1 - y(ispn)/y(ispc)/q_sp_rdf_n
    END IF
    IF (temp .LT. c0) THEN
      max1 = c0
    ELSE
      max1 = temp
    END IF
    excrsp_2c = 0.5*y(ispc)*max1
    IF (excrsp_2c .GT. c0) THEN
      IF (c0 .LT. c1 - y(ispp)/y(ispn)/(q_sp_rdf_p/q_sp_rdf_n)) THEN
        temp = c1 - y(ispp)/y(ispn)/(q_sp_rdf_p/q_sp_rdf_n)
      ELSE
        temp = c0
      END IF
      IF (c0 .LT. c1 - y(ispn)/y(ispp)/(q_sp_rdf_n/q_sp_rdf_p)) THEN
        temp1 = c1 - y(ispn)/y(ispp)/(q_sp_rdf_n/q_sp_rdf_p)
      ELSE
        temp1 = c0
      END IF
      IF (0.25d0*y(ispn)*temp .GT. excrsp_2c*q_sp_rdf_n) THEN
        min1 = excrsp_2c*q_sp_rdf_n
      ELSE
        min1 = 0.25d0*y(ispn)*temp
      END IF
      excrsp_2n = 0.5*min1
      IF (0.25d0*y(ispp)*temp1 .GT. excrsp_2c*q_sp_rdf_p) THEN
        min2 = excrsp_2c*q_sp_rdf_p
      ELSE
        min2 = 0.25d0*y(ispp)*temp1
      END IF
      excrsp_2p = 0.5*min2
    ELSE
      excrsp_2n = c0
      excrsp_2p = c0
    END IF
    excrsp_2c = excrsp_2c + r_excrsp_2*growspc*0.25
! 15N  2
    excrsp_2_15n = excrsp_2n*(rsp/(1.0d0+rsp))
! Aggregation of SP
    pomspc = r_pomsp*y(ispc)*y(ispc)
    pomspn = pomspc*y(ispn)/y(ispc)
! 15N 
    pomsp15n = pomspn*(rsp/(1.0d0+rsp))
    pomspp = pomspc*y(ispp)/y(ispc)
    pomspchl = pomspn*y(ispchl)/y(ispn)
! SP grazed
    grazspc = mu_prt*y(iprtc)*y(ispc)*y(ispc)/(y(ispc)*y(ispc)+g_sp*g_sp&
&     +y(iunc)*y(iunc)/g_un/g_un*g_sp*g_sp+y(ibac)*y(ibac)/g_ba/g_ba*&
&     g_sp*g_sp)
    grazspn = grazspc*y(ispn)/y(ispc)
!--------------------------------------------------------------------
! SP be grazed 
!--------------------------------------------------------------------
    u_sp_graz = grazspn*dt/(y(ispn)+eps)
    IF (0.9d0 .GT. u_sp_graz) THEN
      y3 = u_sp_graz
    ELSE
      y3 = 0.9d0
    END IF
    IF (0.0d0 .LT. y3) THEN
      u_sp_graz = y3
    ELSE
      u_sp_graz = 0.0d0
    END IF
    IF (u_sp_graz .LT. 1.0d-8) THEN
      factor_sp_graz = 1.0d0
    ELSE
      factor_sp_graz = -((1.0d0-u_sp_graz)/u_sp_graz*LOG(1.0d0-u_sp_graz&
&       ))
    END IF
!  SP beta  
    beta_sp_graz = rsp*(1.0d0-epsilon_g/1000.0d0*factor_sp_graz)
! SP15N
    grazsp15n = grazspn*(beta_sp_graz/(1.0d0+beta_sp_graz))
    grazspp = grazspc*y(ispp)/y(ispc)
    grazspchl = grazspn*y(ispchl)/y(ispn)
! SP derivs
    dydtt(ispc) = (growspc-excrsp_1c-excrsp_2c-grazspc-pomspc-respsp)/&
&     secperday
    dydtt(ispn) = (growspn-excrsp_1n-excrsp_2n-grazspn-pomspn)/secperday
    dydtt(isp15n) = (growsp15n-excrsp_1_15n-excrsp_2_15n-grazsp15n-&
&     pomsp15n)/secperday
    dydtt(ispp) = (growspp-excrsp_1p-excrsp_2p-grazspp-pomspp)/secperday
    dydtt(ispchl) = (growspchl-grazspchl-pomspchl)/secperday
!-----------------------------------------------------------------------
!      Trichodesmium Processes
!-----------------------------------------------------------------------
! Primary Production
! Nutrient quota Limitation
    nfunc_tr_n = (y(itrn)/y(itrc)-q_tr_min_n)/(q_tr_rdf_n-q_tr_min_n)
    nfunc_tr_p = (y(itrp)/y(itrc)-q_tr_min_p)/(q_tr_rdf_p-q_tr_min_p)
    IF (nfunc_tr_n .GT. nfunc_tr_p) THEN
      temp = nfunc_tr_p
    ELSE
      temp = nfunc_tr_n
    END IF
    IF (temp .GT. c1) THEN
      temp = c1
    ELSE
      temp = temp
    END IF
    IF (temp .LT. c0) THEN
      temp = c0
    ELSE
      temp = temp
    END IF
    pc_trmax = mu_tr*temp
! Light Limitation
    IF (pc_trmax .GT. c0 .AND. y(itrc) .GT. c0) THEN
      growtrc = y(itrc)*pc_trmax*(c1-EXP(-(alpha_tr*y(itrchl)/y(itrc)*&
&       rlt/pc_trmax)))*EXP(-(a_tr*rlt))
    ELSE
      growtrc = c0
    END IF
    IF (c0 .LT. (q_tr_max_n-y(itrn)/y(itrc))/(q_tr_max_n-q_tr_rdf_n)) &
&   THEN
      v_trmax_n = (q_tr_max_n-y(itrn)/y(itrc))/(q_tr_max_n-q_tr_rdf_n)
    ELSE
      v_trmax_n = c0
    END IF
    IF (c1 .GT. v_trmax_n) THEN
      v_trmax_n = v_trmax_n
    ELSE
      v_trmax_n = c1
    END IF
    growtrnh4 = y(itrc)*v_trn*v_trmax_n*y(inh4)/(y(inh4)+k_nh4tr+y(ino3)&
&     *k_nh4tr/k_no3tr)
    growtrno3 = y(itrc)*v_trn*v_trmax_n*y(ino3)/(y(ino3)+k_no3tr+y(inh4)&
&     *k_no3tr/k_nh4tr)
    result1 = TDAT(iz, istep)
    IF (result1 .LT. 20.0) THEN
      maxtrnf = c0
    ELSE
      y4 = ((y(itrc)+growtrc-growtrno3*zeta)*q_tr_max_n-y(itrn)-&
&       growtrno3-growtrnh4)/(c1+zeta_nf*q_tr_max_n)*v_trmax_n*tfunc
      IF (c0 .LT. y4) THEN
        maxtrnf = y4
      ELSE
        maxtrnf = c0
      END IF
    END IF
    IF (y(itrc)*v_trn*v_trmax_n .GT. growtrnh4 + growtrno3 + maxtrnf) &
&   THEN
      growtrn = growtrnh4 + growtrno3 + maxtrnf
    ELSE
      growtrn = y(itrc)*v_trn*v_trmax_n
    END IF
    growtrnf = growtrn - growtrnh4 - growtrno3
! 15N  
!--------------------------------------------------------------------
! TR N2 fixation 
! --------------------------------------------------------------------
    beta_nf = r_std*(1.0d0-epsilon_nf/1000.0d0)
    growtr15nf = growtrnf*(beta_nf/(1.0d0+beta_nf))
!--------------------------------------------------------------------
! TR NH4 Assimilation 
!--------------------------------------------------------------------
    u_nh4_tr = growtrnh4*dt/(y(inh4)+eps)
    IF (0.9d0 .GT. u_nh4_tr) THEN
      y5 = u_nh4_tr
    ELSE
      y5 = 0.9d0
    END IF
    IF (0.0d0 .LT. y5) THEN
      u_nh4_tr = y5
    ELSE
      u_nh4_tr = 0.0d0
    END IF
    IF (y(inh4) .LT. nh4_limit) THEN
! B
      factor_nh4_tr = 0.0d0
    ELSE IF (u_nh4_tr .LT. 1.0d-8) THEN
! A
      factor_nh4_tr = 1.0d0
    ELSE
      factor_nh4_tr = -((1.0d0-u_nh4_tr)/u_nh4_tr*LOG(1.0d0-u_nh4_tr))
    END IF
! TR NH4 beta  
    beta_nh4_tr = rnh4*(1.0d0-epsilon_anh4/1000.0d0*factor_nh4_tr)
    growtr15nh4 = growtrnh4*(beta_nh4_tr/(1.0d0+beta_nh4_tr))
!--------------------------------------------------------------------
! TR NO3 Assimilation 
!--------------------------------------------------------------------
    u_no3_tr = growtrno3*dt/(y(ino3)+eps)
    IF (0.9d0 .GT. u_no3_tr) THEN
      y6 = u_no3_tr
    ELSE
      y6 = 0.9d0
    END IF
    IF (0.0d0 .LT. y6) THEN
      u_no3_tr = y6
    ELSE
      u_no3_tr = 0.0d0
    END IF
    IF (y(ino3) .LT. no3_limit) THEN
! B
      factor_no3_tr = 0.0d0
    ELSE IF (u_no3_tr .LT. 1.0d-8) THEN
! A
      factor_no3_tr = 1.0d0
    ELSE
      factor_no3_tr = -((1.0d0-u_no3_tr)/u_no3_tr*LOG(1.0d0-u_no3_tr))
    END IF
! TR NO3 beta  
    beta_no3_tr = rno3*(1.0d0-epsilon_ano3/1000.0d0*factor_no3_tr)
!  TR  15N 
    growtr15no3 = growtrno3*(beta_no3_tr/(1.0d0+beta_no3_tr))
    growtr15n = growtr15nh4 + growtr15no3 + growtr15nf
    IF (c0 .LT. (q_tr_max_p-y(itrp)/y(itrc))/(q_tr_max_p-q_tr_rdf_p)) &
&   THEN
      v_trmax_p = (q_tr_max_p-y(itrp)/y(itrc))/(q_tr_max_p-q_tr_rdf_p)
    ELSE
      v_trmax_p = c0
    END IF
    IF (c1 .GT. v_trmax_p) THEN
      v_trmax_p = v_trmax_p
    ELSE
      v_trmax_p = c1
    END IF
    growtrpo4 = y(itrc)*v_trp*v_trmax_p*y(ipo4)/(y(ipo4)+k_po4tr)
    IF (y(itrc)*(q_tr_max_p+q_tr_rdf_p)/2 - y(itrp) .LT. c0) THEN
      max2 = c0
    ELSE
      max2 = y(itrc)*(q_tr_max_p+q_tr_rdf_p)/2 - y(itrp)
    END IF
    picktrpo4 = mu_picktrpo4*max2
    growtrp = growtrpo4 + picktrpo4
! Respiration
    resptr = growtrno3*zeta + growtrnf*zeta_nf
! Chlorophyll
    IF (rlt .GT. c0) THEN
      growtrchl = theta*growtrn*growtrc/(alpha_tr*y(itrchl)*rlt*EXP(-(&
&       a_tr*rlt)))
    ELSE
      growtrchl = c0
    END IF
! TR excretion (mortality)
! Passive
    excrtr_1c = r_excrtr_1*y(itrc) + r_excrtr_2*growtrc*0.75
    IF (c1 .GT. nfunc_tr_n) THEN
      min3 = nfunc_tr_n
    ELSE
      min3 = c1
    END IF
    excrtr_1n = r_excrtr_1*y(itrn) + 0.5*r_excrtr_n*growtrnf*min3
    excrtr_1_15n = excrtr_1n*(rtr/(1.0d0+rtr))
    IF (c1 .GT. nfunc_tr_n) THEN
      min4 = nfunc_tr_n
    ELSE
      min4 = c1
    END IF
    excrtr_nh4 = 0.5*r_excrtr_n*growtrnf*min4
!--------------------------------------------------------------------
! TR NH4 excretion
!--------------------------------------------------------------------
    u_tr_excr = excrtr_nh4*dt/(y(itrn)+eps)
    IF (0.9d0 .GT. u_tr_excr) THEN
      y7 = u_tr_excr
    ELSE
      y7 = 0.9d0
    END IF
    IF (0.0d0 .LT. y7) THEN
      u_tr_excr = y7
    ELSE
      u_tr_excr = 0.0d0
    END IF
    IF (u_tr_excr .LT. 1.0d-8) THEN
      factor_tr_excr = 1.0d0
    ELSE
      factor_tr_excr = -((1.0d0-u_tr_excr)/u_tr_excr*LOG(1.0d0-u_tr_excr&
&       ))
    END IF
    beta_tr_excr = rtr*(1.0d0-epsilon_exnh4/1000.0d0*factor_tr_excr)
    excrtr_15nh4 = excrtr_nh4*(beta_tr_excr/(1.0d0+beta_tr_excr))
    excrtr_1p = r_excrtr_1*y(itrp)
    IF (c1 - y(itrn)/y(itrc)/q_tr_rdf_n .LT. c1 - y(itrp)/y(itrc)/&
&       q_tr_rdf_p) THEN
      temp = c1 - y(itrp)/y(itrc)/q_tr_rdf_p
    ELSE
      temp = c1 - y(itrn)/y(itrc)/q_tr_rdf_n
    END IF
    IF (temp .LT. c0) THEN
      max3 = c0
    ELSE
      max3 = temp
    END IF
    excrtr_2c = r_excrtr_2*y(itrc)*max3
    IF (excrtr_2c .GT. c0) THEN
      IF (c0 .LT. c1 - y(itrp)/y(itrn)/(q_tr_rdf_p/q_tr_rdf_n)) THEN
        temp = c1 - y(itrp)/y(itrn)/(q_tr_rdf_p/q_tr_rdf_n)
      ELSE
        temp = c0
      END IF
      IF (c0 .LT. c1 - y(itrn)/y(itrp)/(q_tr_rdf_n/q_tr_rdf_p)) THEN
        temp1 = c1 - y(itrn)/y(itrp)/(q_tr_rdf_n/q_tr_rdf_p)
      ELSE
        temp1 = c0
      END IF
      IF (0.25d0*y(itrn)*temp .GT. excrtr_2c*q_tr_rdf_n) THEN
        min5 = excrtr_2c*q_tr_rdf_n
      ELSE
        min5 = 0.25d0*y(itrn)*temp
      END IF
      excrtr_2n = r_excrtr_2*min5
      IF (0.25d0*y(itrp)*temp1 .GT. excrtr_2c*q_tr_rdf_p) THEN
        min6 = excrtr_2c*q_tr_rdf_p
      ELSE
        min6 = 0.25d0*y(itrp)*temp1
      END IF
      excrtr_2p = r_excrtr_2*min6
    ELSE
      excrtr_2n = c0
      excrtr_2p = c0
    END IF
    excrtr_2c = excrtr_2c + r_excrtr_2*growtrc*0.25
    excrtr_2_15n = excrtr_2n*(rtr/(1.0d0+rtr))
! Aggregation of TR
    pomtrc = r_pomtr*y(itrc)*y(itrc)
    pomtrn = pomtrc*y(itrn)/y(itrc)
    pomtr15n = pomtrn*(rtr/(1.0d0+rtr))
    pomtrp = pomtrc*y(itrp)/y(itrc)
    pomtrchl = pomtrc*y(itrchl)/y(itrc)
! TR grazed
    graztrc = mu_mz*y(imzc)*y(itrc)*y(itrc)/(y(itrc)*y(itrc)+g_tr*g_tr+y&
&     (iprtc)*y(iprtc)/g_prt/g_prt*g_tr*g_tr)
    graztrn = graztrc*y(itrn)/y(itrc)
!--------------------------------------------------------------------
! TR be grazed 
!--------------------------------------------------------------------
    u_tr_graz = graztrn*dt/(y(itrn)+eps)
    IF (0.9d0 .GT. u_tr_graz) THEN
      y8 = u_tr_graz
    ELSE
      y8 = 0.9d0
    END IF
    IF (0.0d0 .LT. y8) THEN
      u_tr_graz = y8
    ELSE
      u_tr_graz = 0.0d0
    END IF
    IF (u_tr_graz .LT. 1.0d-8) THEN
      factor_tr_graz = 1.0d0
    ELSE
      factor_tr_graz = -((1.0d0-u_tr_graz)/u_tr_graz*LOG(1.0d0-u_tr_graz&
&       ))
    END IF
!  TR beta  
    beta_tr_graz = rtr*(1.0d0-epsilon_g/1000.0d0*factor_tr_graz)
!  TR15N
    graztr15n = graztrn*(beta_tr_graz/(1.0d0+beta_tr_graz))
    graztrp = graztrc*y(itrp)/y(itrc)
    graztrchl = graztrc*y(itrchl)/y(itrc)
! New TR
    dydtt(itrc) = (growtrc-excrtr_1c-excrtr_2c-graztrc-pomtrc-resptr)/&
&     secperday
    dydtt(itrn) = (growtrn-excrtr_1n-excrtr_2n-graztrn-pomtrn-excrtr_nh4&
&     )/secperday
    dydtt(itr15n) = (growtr15n-excrtr_1_15n-excrtr_2_15n-graztr15n-&
&     pomtr15n-excrtr_15nh4)/secperday
    dydtt(itrp) = (growtrp-excrtr_1p-excrtr_2p-graztrp-pomtrp)/secperday
    dydtt(itrchl) = (growtrchl-graztrchl-pomtrchl)/secperday
!-----------------------------------------------------------------------
!      Diatom-Associations Processes
!-----------------------------------------------------------------------
! Primary Production
! Nutrient quota Limitation
    nfunc_dda_n = (y(iddan)/y(iddac)-q_dda_min_n)/(q_dda_rdf_n-&
&     q_dda_min_n)
    nfunc_dda_p = (y(iddap)/y(iddac)-q_dda_min_p)/(q_dda_rdf_p-&
&     q_dda_min_p)
    IF (nfunc_dda_n .GT. nfunc_dda_p) THEN
      temp = nfunc_dda_p
    ELSE
      temp = nfunc_dda_n
    END IF
    IF (temp .GT. c1) THEN
      temp = c1
    ELSE
      temp = temp
    END IF
    IF (temp .LT. c0) THEN
      temp = c0
    ELSE
      temp = temp
    END IF
    pc_ddamax = mu_dda*temp
! Light Limitation
    IF (pc_ddamax .GT. c0 .AND. y(iddac) .GT. c0) THEN
      growddac = y(iddac)*pc_ddamax*(c1-EXP(-(alpha_dda*y(iddachl)/y(&
&       iddac)*rlt/pc_ddamax)))*EXP(-(a_dda*rlt))
    ELSE
      growddac = c0
    END IF
    IF (c0 .LT. (q_dda_max_n-y(iddan)/y(iddac))/(q_dda_max_n-q_dda_rdf_n&
&       )) THEN
      v_ddamax_n = (q_dda_max_n-y(iddan)/y(iddac))/(q_dda_max_n-&
&       q_dda_rdf_n)
    ELSE
      v_ddamax_n = c0
    END IF
    IF (c1 .GT. v_ddamax_n) THEN
      v_ddamax_n = v_ddamax_n
    ELSE
      v_ddamax_n = c1
    END IF
    growddanh4 = y(iddac)*v_ddan*v_ddamax_n*y(inh4)/(y(inh4)+k_nh4dda+y(&
&     ino3)*k_nh4dda/k_no3dda)
    growddano3 = y(iddac)*v_ddan*v_ddamax_n*y(ino3)/(y(ino3)+k_no3dda+y(&
&     inh4)*k_no3dda/k_nh4dda)
    result1 = TDAT(iz, istep)
    IF (result1 .LT. 20.0) THEN
      maxddanf = c0
    ELSE
      y9 = ((y(iddac)+growddac-growddano3*zeta)*q_dda_max_n-y(iddan)-&
&       growddano3-growddanh4)/(c1+zeta_nf_dda*q_dda_max_n)*v_ddamax_n*&
&       tfunc
      IF (c0 .LT. y9) THEN
        maxddanf = y9
      ELSE
        maxddanf = c0
      END IF
    END IF
    IF (y(iddac)*v_ddan*v_ddamax_n .GT. growddanh4 + growddano3 + &
&       maxddanf) THEN
      growddan = growddanh4 + growddano3 + maxddanf
    ELSE
      growddan = y(iddac)*v_ddan*v_ddamax_n
    END IF
    growddanf = growddan - growddanh4 - growddano3
! 15N 
!--------------------------------------------------------------------
! DDA N2 fixation 
!--------------------------------------------------------------------
    beta_nf = r_std*(1.0d0-epsilon_nf/1000.0d0)
    growdda15nf = growddanf*(beta_nf/(1.0d0+beta_nf))
!--------------------------------------------------------------------
! DDA NH4 Assimilation 
!--------------------------------------------------------------------
    u_nh4_dda = growddanh4*dt/(y(inh4)+eps)
    IF (0.9d0 .GT. u_nh4_dda) THEN
      y10 = u_nh4_dda
    ELSE
      y10 = 0.9d0
    END IF
    IF (0.0d0 .LT. y10) THEN
      u_nh4_dda = y10
    ELSE
      u_nh4_dda = 0.0d0
    END IF
    IF (y(inh4) .LT. nh4_limit) THEN
! B
      factor_nh4_dda = 0.0d0
    ELSE IF (u_nh4_dda .LT. 1.0d-8) THEN
! A
      factor_nh4_dda = 1.0d0
    ELSE
      factor_nh4_dda = -((1.0d0-u_nh4_dda)/u_nh4_dda*LOG(1.0d0-u_nh4_dda&
&       ))
    END IF
! TR NH4 beta  
    beta_nh4_dda = rnh4*(1.0d0-epsilon_anh4/1000.0d0*factor_nh4_dda)
    growdda15nh4 = growddanh4*(beta_nh4_dda/(1.0d0+beta_nh4_dda))
!--------------------------------------------------------------------
! DDA NO3 Assimilation 
!--------------------------------------------------------------------
    u_no3_dda = growddano3*dt/(y(ino3)+eps)
    IF (0.9d0 .GT. u_no3_dda) THEN
      y11 = u_no3_dda
    ELSE
      y11 = 0.9d0
    END IF
    IF (0.0d0 .LT. y11) THEN
      u_no3_dda = y11
    ELSE
      u_no3_dda = 0.0d0
    END IF
    IF (y(ino3) .LT. no3_limit) THEN
! B
      factor_no3_dda = 0.0d0
    ELSE IF (u_no3_dda .LT. 1.0d-8) THEN
! A
      factor_no3_dda = 1.0d0
    ELSE
      factor_no3_dda = -((1.0d0-u_no3_dda)/u_no3_dda*LOG(1.0d0-u_no3_dda&
&       ))
    END IF
! DDA NO3 beta  
    beta_no3_dda = rno3*(1.0d0-epsilon_ano3/1000.0d0*factor_no3_dda)
!  DDA  15N 
    growdda15no3 = growddano3*(beta_no3_dda/(1.0d0+beta_no3_dda))
    growdda15n = growdda15nh4 + growdda15no3 + growdda15nf
    IF (c0 .LT. (q_dda_max_p-y(iddap)/y(iddac))/(q_dda_max_p-q_dda_rdf_p&
&       )) THEN
      v_ddamax_p = (q_dda_max_p-y(iddap)/y(iddac))/(q_dda_max_p-&
&       q_dda_rdf_p)
    ELSE
      v_ddamax_p = c0
    END IF
    IF (c1 .GT. v_ddamax_p) THEN
      v_ddamax_p = v_ddamax_p
    ELSE
      v_ddamax_p = c1
    END IF
    growddapo4 = y(iddac)*v_ddap*v_ddamax_p*y(ipo4)/(y(ipo4)+k_po4dda)
    IF (y(iddac)*(q_dda_max_p+q_dda_rdf_p)/2 - y(iddap) .LT. c0) THEN
      max4 = c0
    ELSE
      max4 = y(iddac)*(q_dda_max_p+q_dda_rdf_p)/2 - y(iddap)
    END IF
    pickddapo4 = mu_pickddapo4*max4
    growddap = growddapo4 + pickddapo4
! Respiration
    respdda = growddano3*zeta + growddanf*zeta_nf_dda
! Chlorophyll
    IF (rlt .GT. c0) THEN
      growddachl = theta*growddan*growddac/(alpha_dda*y(iddachl)*rlt*EXP&
&       (-(a_dda*rlt)))
    ELSE
      growddachl = c0
    END IF
! DDA excretion (mortality)
! Passive
    excrdda_1c = r_excrdda_1*y(iddac) + r_excrdda_2*growddac*0.75
    IF (c1 .GT. nfunc_dda_n) THEN
      min7 = nfunc_dda_n
    ELSE
      min7 = c1
    END IF
    excrdda_1n = r_excrdda_1*y(iddan) + 0.5*r_excrdda_n*growddanf*min7
    excrdda_1p = r_excrdda_1*y(iddap)
    IF (c1 .GT. nfunc_dda_n) THEN
      min8 = nfunc_dda_n
    ELSE
      min8 = c1
    END IF
    excrdda_nh4 = 0.5*r_excrdda_n*growddanf*min8
    excrdda_1_15n = excrdda_1n*(rdda/(1.0d0+rdda))
!-------------------------------------------------------------------
! DDA NH4 excretion
!--------------------------------------------------------------------
    u_dda_excr = excrdda_nh4*dt/(y(iddan)+eps)
    IF (0.9d0 .GT. u_dda_excr) THEN
      y12 = u_dda_excr
    ELSE
      y12 = 0.9d0
    END IF
    IF (0.0d0 .LT. y12) THEN
      u_dda_excr = y12
    ELSE
      u_dda_excr = 0.0d0
    END IF
    IF (u_dda_excr .LT. 1.0d-8) THEN
      factor_dda_excr = 1.0d0
    ELSE
      factor_dda_excr = -((1.0d0-u_dda_excr)/u_dda_excr*LOG(1.0d0-&
&       u_dda_excr))
    END IF
    beta_dda_excr = rdda*(1.0d0-epsilon_exnh4/1000.0d0*factor_dda_excr)
    excrdda_15nh4 = excrdda_nh4*(beta_dda_excr/(1.0d0+beta_dda_excr))
    IF (c1 - y(iddan)/y(iddac)/q_dda_rdf_n .LT. c1 - y(iddap)/y(iddac)/&
&       q_dda_rdf_p) THEN
      temp = c1 - y(iddap)/y(iddac)/q_dda_rdf_p
    ELSE
      temp = c1 - y(iddan)/y(iddac)/q_dda_rdf_n
    END IF
    IF (temp .LT. c0) THEN
      max5 = c0
    ELSE
      max5 = temp
    END IF
    excrdda_2c = r_excrdda_2*y(iddac)*max5
    IF (excrdda_2c .GT. c0) THEN
      IF (c0 .LT. c1 - y(iddap)/y(iddan)/(q_dda_rdf_p/q_dda_rdf_n)) THEN
        temp = c1 - y(iddap)/y(iddan)/(q_dda_rdf_p/q_dda_rdf_n)
      ELSE
        temp = c0
      END IF
      IF (c0 .LT. c1 - y(iddan)/y(iddap)/(q_dda_rdf_n/q_dda_rdf_p)) THEN
        temp1 = c1 - y(iddan)/y(iddap)/(q_dda_rdf_n/q_dda_rdf_p)
      ELSE
        temp1 = c0
      END IF
      IF (0.25d0*y(iddan)*temp .GT. excrdda_2c*q_dda_rdf_n) THEN
        min9 = excrdda_2c*q_dda_rdf_n
      ELSE
        min9 = 0.25d0*y(iddan)*temp
      END IF
      excrdda_2n = r_excrdda_2*min9
      IF (0.25d0*y(iddap)*temp1 .GT. excrdda_2c*q_dda_rdf_p) THEN
        min10 = excrdda_2c*q_dda_rdf_p
      ELSE
        min10 = 0.25d0*y(iddap)*temp1
      END IF
      excrdda_2p = r_excrdda_2*min10
    ELSE
      excrdda_2n = c0
      excrdda_2p = c0
    END IF
    excrdda_2c = excrdda_2c + r_excrdda_2*growddac*0.25
    excrdda_2_15n = excrdda_2n*(rdda/(1.0d0+rdda))
! Aggregation of DDA
    pomddac = r_pomdda*y(iddac)*y(iddac)
    pomddan = pomddac*y(iddan)/y(iddac)
    pomdda15n = pomddan*(rdda/(1.0d0+rdda))
    pomddap = pomddac*y(iddap)/y(iddac)
    pomddachl = pomddac*y(iddachl)/y(iddac)
! DDA grazed
    grazddac = mu_mz*y(imzc)*y(iddac)*y(iddac)/(y(iddac)*y(iddac)+g_dda*&
&     g_dda+y(iprtc)*y(iprtc)/g_prt/g_prt*g_dda*g_dda)
    grazddan = grazddac*y(iddan)/y(iddac)
!--------------------------------------------------------------------
! DDA be grazed 
!--------------------------------------------------------------------
    u_dda_graz = grazddan*dt/(y(iddan)+eps)
    IF (0.9d0 .GT. u_dda_graz) THEN
      y13 = u_dda_graz
    ELSE
      y13 = 0.9d0
    END IF
    IF (0.0d0 .LT. y13) THEN
      u_dda_graz = y13
    ELSE
      u_dda_graz = 0.0d0
    END IF
    IF (u_dda_graz .LT. 1.0d-8) THEN
      factor_dda_graz = 1.0d0
    ELSE
      factor_dda_graz = -((1.0d0-u_dda_graz)/u_dda_graz*LOG(1.0d0-&
&       u_dda_graz))
    END IF
! DDA beta  
    beta_dda_graz = rdda*(1.0d0-epsilon_g/1000.0d0*factor_dda_graz)
! DDA15N
    grazdda15n = grazddan*(beta_dda_graz/(1.0d0+beta_dda_graz))
    grazddap = grazddac*y(iddap)/y(iddac)
    grazddachl = grazddac*y(iddachl)/y(iddac)
! New DDA
    dydtt(iddac) = (growddac-excrdda_1c-excrdda_2c-grazddac-pomddac-&
&     respdda)/secperday
    dydtt(iddan) = (growddan-excrdda_1n-excrdda_2n-grazddan-pomddan-&
&     excrdda_nh4)/secperday
    dydtt(idda15n) = (growdda15n-excrdda_1_15n-excrdda_2_15n-grazdda15n-&
&     pomdda15n-excrdda_15nh4)/secperday
    dydtt(iddap) = (growddap-excrdda_1p-excrdda_2p-grazddap-pomddap)/&
&     secperday
    dydtt(iddachl) = (growddachl-grazddachl-pomddachl)/secperday
!-----------------------------------------------------------------------
! Unicellular N2-fixers Processes
!-----------------------------------------------------------------------
! Primary Production
! Nutrient quota Limitation
    nfunc_un_n = (y(iunn)/y(iunc)-q_un_min_n)/(q_un_rdf_n-q_un_min_n)
    nfunc_un_p = (y(iunp)/y(iunc)-q_un_min_p)/(q_un_rdf_p-q_un_min_p)
    IF (nfunc_un_n .GT. nfunc_un_p) THEN
      temp = nfunc_un_p
    ELSE
      temp = nfunc_un_n
    END IF
    IF (temp .GT. c1) THEN
      temp = c1
    ELSE
      temp = temp
    END IF
    IF (temp .LT. c0) THEN
      temp = c0
    ELSE
      temp = temp
    END IF
    pc_unmax = mu_un*temp
! Light Limitation
    IF (pc_unmax .GT. c0 .AND. y(iunc) .GT. c0) THEN
      growunc = y(iunc)*pc_unmax*(c1-EXP(-(alpha_un*y(iunchl)/y(iunc)*&
&       rlt/pc_unmax)))*EXP(-(a_un*rlt))
    ELSE
      growunc = c0
    END IF
    IF (c0 .LT. (q_un_max_n-y(iunn)/y(iunc))/(q_un_max_n-q_un_rdf_n)) &
&   THEN
      v_unmax_n = (q_un_max_n-y(iunn)/y(iunc))/(q_un_max_n-q_un_rdf_n)
    ELSE
      v_unmax_n = c0
    END IF
    IF (c1 .GT. v_unmax_n) THEN
      v_unmax_n = v_unmax_n
    ELSE
      v_unmax_n = c1
    END IF
    growunnh4 = y(iunc)*v_unn*v_unmax_n*y(inh4)/(y(inh4)+k_nh4un+y(ino3)&
&     *k_nh4un/k_no3un)
    growunno3 = y(iunc)*v_unn*v_unmax_n*y(ino3)/(y(ino3)+k_no3un+y(inh4)&
&     *k_no3un/k_nh4un)
    y14 = ((y(iunc)-growunc-growunno3*zeta)*q_un_max_n-y(iunn)-growunno3&
&     -growunnh4)/(c1+zeta_nf*q_un_max_n)*v_unmax_n*tfunc
    IF (c0 .LT. y14) THEN
      maxunnf = y14
    ELSE
      maxunnf = c0
    END IF
    IF (y(iunc)*v_unn*v_unmax_n .GT. growunnh4 + growunno3 + maxunnf) &
&   THEN
      growunn = growunnh4 + growunno3 + maxunnf
    ELSE
      growunn = y(iunc)*v_unn*v_unmax_n
    END IF
    growunnf = growunn - growunnh4 - growunno3
! 15N 
!--------------------------------------------------------------------
! UN N2 fixation 
!--------------------------------------------------------------------
    beta_nf = r_std*(1.0d0-epsilon_nf/1000.0d0)
    growun15nf = growunnf*(beta_nf/(1.0d0+beta_nf))
!--------------------------------------------------------------------
! UN NH4 Assimilation 
!--------------------------------------------------------------------
    u_nh4_un = growunnh4*dt/(y(inh4)+eps)
    IF (0.9d0 .GT. u_nh4_un) THEN
      y15 = u_nh4_un
    ELSE
      y15 = 0.9d0
    END IF
    IF (0.0d0 .LT. y15) THEN
      u_nh4_un = y15
    ELSE
      u_nh4_un = 0.0d0
    END IF
    IF (y(inh4) .LT. nh4_limit) THEN
! B
      factor_nh4_un = 0.0d0
    ELSE IF (u_nh4_un .LT. 1.0d-8) THEN
! A
      factor_nh4_un = 1.0d0
    ELSE
      factor_nh4_un = -((1.0d0-u_nh4_un)/u_nh4_un*LOG(1.0d0-u_nh4_un))
    END IF
! UN NH4 beta  
    beta_nh4_un = rnh4*(1.0d0-epsilon_anh4/1000.0d0*factor_nh4_un)
    growun15nh4 = growunnh4*(beta_nh4_un/(1.0d0+beta_nh4_un))
!--------------------------------------------------------------------
! UN NO3 Assimilation 
!--------------------------------------------------------------------
    u_no3_un = growunno3*dt/(y(ino3)+eps)
    IF (0.9d0 .GT. u_no3_un) THEN
      y16 = u_no3_un
    ELSE
      y16 = 0.9d0
    END IF
    IF (0.0d0 .LT. y16) THEN
      u_no3_un = y16
    ELSE
      u_no3_un = 0.0d0
    END IF
    IF (y(ino3) .LT. no3_limit) THEN
! B
      factor_no3_un = 0.0d0
    ELSE IF (u_no3_un .LT. 1.0d-8) THEN
! A
      factor_no3_un = 1.0d0
    ELSE
      factor_no3_un = -((1.0d0-u_no3_un)/u_no3_un*LOG(1.0d0-u_no3_un))
    END IF
! UN NO3 beta  
    beta_no3_un = rno3*(1.0d0-epsilon_ano3/1000.0d0*factor_no3_un)
    growun15no3 = growunno3*(beta_no3_un/(1.0d0+beta_no3_un))
    growun15n = growun15nh4 + growun15no3 + growun15nf
    IF (c0 .LT. (q_un_max_p-y(iunp)/y(iunc))/(q_un_max_p-q_un_rdf_p)) &
&   THEN
      v_unmax_p = (q_un_max_p-y(iunp)/y(iunc))/(q_un_max_p-q_un_rdf_p)
    ELSE
      v_unmax_p = c0
    END IF
    IF (c1 .GT. v_unmax_p) THEN
      v_unmax_p = v_unmax_p
    ELSE
      v_unmax_p = c1
    END IF
    growunp = y(iunc)*v_unp*v_unmax_p*y(ipo4)/(y(ipo4)+k_po4un)
    respun = growunno3*zeta + growunnf*zeta_nf
! Chlorophyll
    IF (rlt .GT. c0) THEN
      growunchl = theta*growunn*growunc/(alpha_un*y(iunchl)*rlt*EXP(-(&
&       a_un*rlt)))
    ELSE
      growunchl = c0
    END IF
! UN excretion
! Passive
    excrun_1c = r_excrun_1*y(iunc) + r_excrun_2*growunc*0.75
    IF (c1 .GT. nfunc_un_n) THEN
      min11 = nfunc_un_n
    ELSE
      min11 = c1
    END IF
    excrun_1n = r_excrun_1*y(iunn) + 0.5*r_excrun_n*growunnf*min11
    IF (c1 .GT. nfunc_un_n) THEN
      min12 = nfunc_un_n
    ELSE
      min12 = c1
    END IF
    excrun_nh4 = 0.5*r_excrun_n*growunnf*min12
    excrun_1_15n = excrun_1n*(run/(1.0d0+run))
!-------------------------------------------------------------------
! UN NH4 excretion
!--------------------------------------------------------------------
    u_un_excr = excrun_nh4*dt/(y(iunn)+eps)
    IF (0.9d0 .GT. u_un_excr) THEN
      y17 = u_un_excr
    ELSE
      y17 = 0.9d0
    END IF
    IF (0.0d0 .LT. y17) THEN
      u_un_excr = y17
    ELSE
      u_un_excr = 0.0d0
    END IF
    IF (u_un_excr .LT. 1.0d-8) THEN
      factor_un_excr = 1.0d0
    ELSE
      factor_un_excr = -((1.0d0-u_un_excr)/u_un_excr*LOG(1.0d0-u_un_excr&
&       ))
    END IF
    beta_un_excr = run*(1.0d0-epsilon_exnh4/1000.0d0*factor_un_excr)
    excrun_15nh4 = excrun_nh4*(beta_un_excr/(1.0d0+beta_un_excr))
    excrun_1p = r_excrun_1*y(iunp)
    IF (c1 - y(iunn)/y(iunc)/q_un_rdf_n .LT. c1 - y(iunp)/y(iunc)/&
&       q_un_rdf_p) THEN
      temp = c1 - y(iunp)/y(iunc)/q_un_rdf_p
    ELSE
      temp = c1 - y(iunn)/y(iunc)/q_un_rdf_n
    END IF
    IF (temp .LT. c0) THEN
      max6 = c0
    ELSE
      max6 = temp
    END IF
    excrun_2c = r_excrun_2*y(iunc)*max6
    IF (excrun_2c .GT. c0) THEN
      IF (c0 .LT. c1 - y(iunp)/y(iunn)/(q_un_rdf_p/q_un_rdf_n)) THEN
        temp = c1 - y(iunp)/y(iunn)/(q_un_rdf_p/q_un_rdf_n)
      ELSE
        temp = c0
      END IF
      IF (c0 .LT. c1 - y(iunn)/y(iunp)/(q_un_rdf_n/q_un_rdf_p)) THEN
        temp1 = c1 - y(iunn)/y(iunp)/(q_un_rdf_n/q_un_rdf_p)
      ELSE
        temp1 = c0
      END IF
      IF (0.25d0*y(iunn)*temp .GT. excrun_2c*q_un_rdf_n) THEN
        min13 = excrun_2c*q_un_rdf_n
      ELSE
        min13 = 0.25d0*y(iunn)*temp
      END IF
      excrun_2n = r_excrun_2*min13
      IF (0.25d0*y(iunp)*temp1 .GT. excrun_2c*q_un_rdf_p) THEN
        min14 = excrun_2c*q_un_rdf_p
      ELSE
        min14 = 0.25d0*y(iunp)*temp1
      END IF
      excrun_2p = r_excrun_2*min14
    ELSE
      excrun_2n = c0
      excrun_2p = c0
    END IF
    excrun_2c = excrun_2c + r_excrun_2*growunc*0.25
    excrun_2_15n = excrun_2n*(run/(1.0d0+run))
! Aggregation of UN
    pomunc = r_pomun*y(iunc)*y(iunc)
    pomunn = pomunc*y(iunn)/y(iunc)
    pomun15n = pomunn*(run/(1.0d0+run))
    pomunp = pomunc*y(iunp)/y(iunc)
    pomunchl = pomunc*y(iunchl)/y(iunc)
! UN grazed
    grazunc = mu_prt*y(iprtc)*y(iunc)*y(iunc)/(y(iunc)*y(iunc)+g_un*g_un&
&     +y(ispc)*y(ispc)/g_sp/g_sp*g_un*g_un+y(ibac)*y(ibac)/g_ba/g_ba*&
&     g_un*g_un)
    grazunn = grazunc*y(iunn)/y(iunc)
!--------------------------------------------------------------------
! UN be grazed 
!--------------------------------------------------------------------
    u_un_graz = grazunn*dt/(y(iunn)+eps)
    IF (0.9d0 .GT. u_un_graz) THEN
      y18 = u_un_graz
    ELSE
      y18 = 0.9d0
    END IF
    IF (0.0d0 .LT. y18) THEN
      u_un_graz = y18
    ELSE
      u_un_graz = 0.0d0
    END IF
    IF (u_un_graz .LT. 1.0d-8) THEN
      factor_un_graz = 1.0d0
    ELSE
      factor_un_graz = -((1.0d0-u_un_graz)/u_un_graz*LOG(1.0d0-u_un_graz&
&       ))
    END IF
!UN beta  
    beta_un_graz = run*(1.0d0-epsilon_g/1000.0d0*factor_un_graz)
! UN15N
    grazun15n = grazunn*(beta_un_graz/(1.0d0+beta_un_graz))
    grazunp = grazunc*y(iunp)/y(iunc)
    grazunchl = grazunc*y(iunchl)/y(iunc)
! New UN
    dydtt(iunc) = (growunc-excrun_1c-excrun_2c-grazunc-pomunc-respun)/&
&     secperday
    dydtt(iunn) = (growunn-excrun_1n-excrun_2n-grazunn-pomunn-excrun_nh4&
&     )/secperday
    dydtt(iun15n) = (growun15n-excrun_1_15n-excrun_2_15n-grazun15n-&
&     pomun15n-excrun_15nh4)/secperday
    dydtt(iunp) = (growunp-excrun_1p-excrun_2p-grazunp-pomunp)/secperday
    dydtt(iunchl) = (growunchl-grazunchl-pomunchl)/secperday
!-----------------------------------------------------------------------
!      Bacterial Processes
!-----------------------------------------------------------------------
! 1. Gross Grow
! Maximum possible C amount for bacterial use
    alc = y(ildomc)
!temp = MIN(c1, exp(b_SDONlabi * (y(iSDOMn)/y(iSDOMc)/q_BA_n - c1)) )
!temp = MIN(temp, exp(b_SDOPlabi * (y(iSDOMp)/y(iSDOMc)/q_BA_p - c1)) )
    asc = y(isdomc)*r_sdom
! Carbon Usage
    nfunc_ba_n = y(iban)/y(ibac)/q_ba_n
    nfunc_ba_p = y(ibap)/y(ibac)/q_ba_p
    IF (nfunc_ba_n .GT. nfunc_ba_p) THEN
      temp = nfunc_ba_p
    ELSE
      temp = nfunc_ba_n
    END IF
    IF (temp .GT. c1) THEN
      temp = c1
    ELSE
      temp = temp
    END IF
    growbaldoc = mu_ba*y(ibac)*temp*alc/(alc+k_dom+asc)
    growbasdoc = mu_ba*y(ibac)*temp*asc/(asc+k_dom+alc)
! DON and DOP usage
! available labile N
    growbaldon = growbaldoc/y(ildomc)*y(ildomn)
! available labile P
    growbaldop = growbaldoc/y(ildomc)*y(ildomp)
    y19 = y(isdomn)/y(isdomc) + f_baslct/nfunc_ba_n*(q_ba_n-y(isdomn)/y(&
&     isdomc))
    IF (q_ba_n .GT. y19) THEN
      min15 = y19
    ELSE
      min15 = q_ba_n
    END IF
    growbasdon = growbasdoc*min15
    y20 = y(isdomp)/y(isdomc) + f_baslct/nfunc_ba_p*(q_ba_p-y(isdomp)/y(&
&     isdomc))
    IF (q_ba_p .GT. y20) THEN
      min16 = y20
    ELSE
      min16 = q_ba_p
    END IF
    growbasdop = growbasdoc*min16
! 15N DON 
    growba15ldon = growbaldon*(rldom/(1.0d0+rldom))
    growba15sdon = growbasdon*(rldom/(1.0d0+rldom))
    IF (c1 .GT. 1/nfunc_ba_n) THEN
      min17 = 1/nfunc_ba_n
    ELSE
      min17 = c1
    END IF
! inorganic nutrients uptake
    growbanh4 = growbaldon/y(ildomn)*y(inh4)*min17
    IF (nfunc_ba_n .LT. c1) THEN
      IF (c1 .GT. 1/nfunc_ba_n) THEN
        min19 = 1/nfunc_ba_n
      ELSE
        min19 = c1
      END IF
      x1 = 0.1*(growbaldon+growbasdon)/(y(ildomn)+y(isdomn))*y(ino3)*&
&       min19
      IF (x1 .GT. (growbaldon+growbasdon)/(y(ildomn)+y(isdomn))*(y(ino3)&
&         +y(inh4)) - growbanh4) THEN
        growbano3 = (growbaldon+growbasdon)/(y(ildomn)+y(isdomn))*(y(&
&         ino3)+y(inh4)) - growbanh4
      ELSE
        growbano3 = x1
      END IF
      IF (c0 .LT. growbano3) THEN
        growbano3 = growbano3
      ELSE
        growbano3 = c0
      END IF
    ELSE
      growbano3 = c0
    END IF
    IF (c1 .GT. 1/nfunc_ba_p) THEN
      min18 = 1/nfunc_ba_p
    ELSE
      min18 = c1
    END IF
    growbapo4 = growbaldop/y(ildomp)*y(ipo4)*min18
! 15N 
!--------------------------------------------------------------------
! BA NH4 Assimilation 
!--------------------------------------------------------------------
    u_nh4_ba = growbanh4*dt/(y(inh4)+eps)
    IF (0.9d0 .GT. u_nh4_ba) THEN
      y21 = u_nh4_ba
    ELSE
      y21 = 0.9d0
    END IF
    IF (0.0d0 .LT. y21) THEN
      u_nh4_ba = y21
    ELSE
      u_nh4_ba = 0.0d0
    END IF
    IF (y(inh4) .LT. nh4_limit) THEN
! B
      factor_nh4_ba = 0.0d0
    ELSE IF (u_nh4_ba .LT. 1.0d-8) THEN
! A
      factor_nh4_ba = 1.0d0
    ELSE
      factor_nh4_ba = -((1.0d0-u_nh4_ba)/u_nh4_ba*LOG(1.0d0-u_nh4_ba))
    END IF
!BA NH4 beta  
    beta_nh4_ba = rnh4*(1.0d0-epsilon_anh4/1000.0d0*factor_nh4_ba)
    growba15nh4 = growbanh4*(beta_nh4_ba/(1.0d0+beta_nh4_ba))
!--------------------------------------------------------------------
! BA NO3 Assimilation 
!--------------------------------------------------------------------
    u_no3_ba = growbano3*dt/(y(ino3)+eps)
    IF (0.9d0 .GT. u_no3_ba) THEN
      y22 = u_no3_ba
    ELSE
      y22 = 0.9d0
    END IF
    IF (0.0d0 .LT. y22) THEN
      u_no3_ba = y22
    ELSE
      u_no3_ba = 0.0d0
    END IF
    IF (y(ino3) .LT. no3_limit) THEN
! B
      factor_no3_ba = 0.0d0
    ELSE IF (u_no3_ba .LT. 1.0d-8) THEN
! A
      factor_no3_ba = 1.0d0
    ELSE
      factor_no3_ba = -((1.0d0-u_no3_ba)/u_no3_ba*LOG(1.0d0-u_no3_ba))
    END IF
! BA NO3 beta  
    beta_no3_ba = rno3*(1.0d0-epsilon_ano3/1000.0d0*factor_no3_ba)
    growba15no3 = growbano3*(beta_no3_ba/(1.0d0+beta_no3_ba))
! Bacteria gross growth
    growbac = growbaldoc + growbasdoc
    growban = growbaldon + growbasdon + growbanh4 + growbano3
    growba15n = growba15ldon + growba15sdon + growba15nh4 + growba15no3
    growbap = growbaldop + growbasdop + growbapo4
! 2. respiration
    respba = r_baresp_1*y(ibac) + zeta*growbano3 + (r_baresp_min+(&
&     r_baresp_max-r_baresp_min)*EXP(-(b_baresp*growbac)))*growbac
! 3. excreting refractory DOM
    refrbac = r_barefr*y(ibac)
    refrban = q_refrdom_n*refrbac
    refrba15n = refrban*(rba/(1.0d0+rba))
    refrbap = q_refrdom_p*refrbac
! 4. excreting semi-labile DOM and regenerating DIN
    IF (y(ibac) .LT. y(iban)/q_ba_n .AND. y(ibac) .LT. y(ibap)/q_ba_p) &
&   THEN
!Cabon in short
      excrbac = c0
      excrban = c0
      excrbap = c0
      remiban = r_baremi*(y(iban)-y(ibac)*q_ba_n)
      remibap = r_baremi*(y(ibap)-y(ibac)*q_ba_p)
    ELSE IF (y(ibac) .GT. y(iban)/q_ba_n .AND. y(ibap)/q_ba_p .GT. y(&
&       iban)/q_ba_n) THEN
!Nitrogen in short
      excrbac = r_baadju*(y(ibac)-y(iban)/q_ba_n)
      excrban = c0
      excrbap = r_baadju*(y(ibap)-y(iban)/q_ba_n*q_ba_p)
      remiban = c0
      remibap = c0
    ELSE
!Phosphorus in short
      excrbac = r_baadju*(y(ibac)-y(ibap)/q_ba_p)
      excrban = r_baadju*(y(iban)-y(ibap)/q_ba_p*q_ba_n)
      excrbap = c0
      remiban = c0
      remibap = c0
    END IF
    excrba15n = excrban*(rba/(1.0d0+rba))
! BA beta  
    beta_ba_remi = rba*(1.0d0-epsilon_remin/1000.0d0)
! BA15N
    remiba15n = remiban*(beta_ba_remi/(1.0d0+beta_ba_remi))
!6. removal by grazing
    grazbac = mu_prt*y(iprtc)*y(ibac)*y(ibac)/(y(ibac)*y(ibac)+g_ba*g_ba&
&     +y(ispc)*y(ispc)/g_sp/g_sp*g_ba*g_ba+y(iunc)*y(iunc)/g_un/g_un*&
&     g_ba*g_ba)
    grazban = grazbac/y(ibac)*y(iban)
!--------------------------------------------------------------------
! BA be grazed 
!--------------------------------------------------------------------
    u_ba_graz = grazban*dt/(y(iban)+eps)
    IF (0.9d0 .GT. u_ba_graz) THEN
      y23 = u_ba_graz
    ELSE
      y23 = 0.9d0
    END IF
    IF (0.0d0 .LT. y23) THEN
      u_ba_graz = y23
    ELSE
      u_ba_graz = 0.0d0
    END IF
    IF (u_ba_graz .LT. 1.0d-8) THEN
      factor_ba_graz = 1.0d0
    ELSE
      factor_ba_graz = -((1.0d0-u_ba_graz)/u_ba_graz*LOG(1.0d0-u_ba_graz&
&       ))
    END IF
!  BA beta  
    beta_ba_graz = rba*(1.0d0-epsilon_g/1000.0d0*factor_ba_graz)
! BA15N
    grazba15n = grazban*(beta_ba_graz/(1.0d0+beta_ba_graz))
    grazbap = grazbac/y(ibac)*y(ibap)
!6b. Mortality due to viruses
    mortbac = r_bamort*y(ibac)
    mortban = r_bamort*y(iban)
    mortba15n = mortban*(rba/(1.0d0+rba))
    mortbap = r_bamort*y(ibap)
!7. BA Derivs
    dydtt(ibac) = (growbac-excrbac-grazbac-respba-mortbac)/secperday
    dydtt(iban) = (growban-excrban-remiban-grazban-mortban)/secperday
    dydtt(iba15n) = (growba15n-excrba15n-remiba15n-grazba15n-mortba15n)/&
&     secperday
    dydtt(ibap) = (growbap-excrbap-remibap-grazbap-mortbap)/secperday
!8. Flux of inorganic nutrients through bacteria
    fluxbanh4 = growbanh4 - remiban
    fluxbano3 = growbano3
    fluxba15nh4 = growba15nh4 - remiba15n
    fluxba15no3 = growba15no3
    fluxbapo4 = growbapo4 - remibap
!-----------------------------------------------------------------------
!      Protozoan Processes
!-----------------------------------------------------------------------
! 1. gross growth
    growprtc = grazspc + grazbac + grazunc
    growprtn = grazspn + grazban + grazunn
    growprt15n = grazsp15n + grazba15n + grazun15n
    growprtp = grazspp + grazbap + grazunp
! 2. DOM excretion
    excrprtldomc = f_exprtldom*r_prtex*growprtc
    excrprtldomn = f_exprtldom*r_prtex*growprtn
    excrprtldom15n = f_exprtldom*r_prtex*growprt15n
    excrprtldomp = f_exprtldom*r_prtex*growprtp
    excrprtsdomc = (c1-f_exprtldom)*r_prtex*growprtc
    excrprtsdomn = (c1-f_exprtldom)*r_prtex*growprtn*y(iprtn)/y(iprtc)/&
&     q_prt_n
    excrprtsdom15n = excrprtsdomn*(rprt/(1.0d0+rprt))
    excrprtsdomp = (c1-f_exprtldom)*r_prtex*growprtp*y(iprtp)/y(iprtc)/&
&     q_prt_p
! 3. respiration
    respprt = r_prtresp_1*y(iprtc) + r_prtresp_2*growprtc
    IF (c1 - y(iprtn)/y(iprtc)/q_prt_n .LT. c1 - y(iprtp)/y(iprtc)/&
&       q_prt_p) THEN
      temp = c1 - y(iprtp)/y(iprtc)/q_prt_p
    ELSE
      temp = c1 - y(iprtn)/y(iprtc)/q_prt_n
    END IF
    IF (c0 .LT. temp) THEN
      temp = temp
    ELSE
      temp = c0
    END IF
    excrprtsdom2c = r_prtadju*y(iprtc)*temp
    excrprtsdom2n = 0.5d0*excrprtsdom2c*y(iprtn)/y(iprtc)
    excrprtsdom2_15n = excrprtsdom2n*(rprt/(1.0d0+rprt))
    excrprtsdom2p = 0.5d0*excrprtsdom2c*y(iprtp)/y(iprtc)
    IF (r_prtremi*(y(iprtn)-q_prt_n*y(iprtc)) .LT. r_prtremi*(y(iprtn)-&
&       q_prt_n/q_prt_p*y(iprtp))) THEN
      remiprtn = r_prtremi*(y(iprtn)-q_prt_n/q_prt_p*y(iprtp))
    ELSE
      remiprtn = r_prtremi*(y(iprtn)-q_prt_n*y(iprtc))
    END IF
    IF (c0 .LT. remiprtn) THEN
      remiprtn = remiprtn
    ELSE
      remiprtn = c0
    END IF
!PRT beta  
    beta_prt_remi = rprt*(1.0d0-epsilon_remin/1000.0d0)
!PRT15N
    remiprt15n = remiprtn*(beta_prt_remi/(1.0d0+beta_prt_remi))
    IF (r_prtremi*(y(iprtp)-q_prt_p*y(iprtc)) .LT. r_prtremi*(y(iprtp)-&
&       q_prt_p/q_prt_n*y(iprtn))) THEN
      remiprtp = r_prtremi*(y(iprtp)-q_prt_p/q_prt_n*y(iprtn))
    ELSE
      remiprtp = r_prtremi*(y(iprtp)-q_prt_p*y(iprtc))
    END IF
    IF (c0 .LT. remiprtp) THEN
      remiprtp = remiprtp
    ELSE
      remiprtp = c0
    END IF
! POM production
    pomprtc = r_pomprt*growprtc
    pomprtn = pomprtc*q_pom_n
    pomprt15n = pomprtn*(rprt/(1.0d0+rprt))
    pomprtp = pomprtc*q_pom_p
! 6. removal by microzooplankton
    grazprtc = mu_mz*y(imzc)*y(iprtc)*y(iprtc)/(y(iprtc)*y(iprtc)+g_prt*&
&     g_prt+y(itrc)*y(itrc)/g_tr/g_tr*g_prt*g_prt+y(iddac)*y(iddac)/&
&     g_dda/g_dda*g_prt*g_prt)
    grazprtn = grazprtc*y(iprtn)/y(iprtc)
!--------------------------------------------------------------------
! PRT be grazed 
!--------------------------------------------------------------------
    u_prt_graz = grazprtn*dt/(y(iprtn)+eps)
    IF (0.9d0 .GT. u_prt_graz) THEN
      y24 = u_prt_graz
    ELSE
      y24 = 0.9d0
    END IF
    IF (0.0d0 .LT. y24) THEN
      u_prt_graz = y24
    ELSE
      u_prt_graz = 0.0d0
    END IF
    IF (u_prt_graz .LT. 1.0d-8) THEN
      factor_prt_graz = 1.0d0
    ELSE
      factor_prt_graz = -((1.0d0-u_prt_graz)/u_prt_graz*LOG(1.0d0-&
&       u_prt_graz))
    END IF
!  PRT beta  
    beta_prt_graz = rprt*(1.0d0-epsilon_g/1000.0d0*factor_prt_graz)
! PRT15N
    grazprt15n = grazprtn*(beta_prt_graz/(1.0d0+beta_prt_graz))
    grazprtp = grazprtc*y(iprtp)/y(iprtc)
! 7. new PRT
    dydtt(iprtc) = (growprtc-excrprtldomc-excrprtsdomc-excrprtsdom2c-&
&     grazprtc-pomprtc-respprt)/secperday
    dydtt(iprtn) = (growprtn-excrprtldomn-excrprtsdomn-excrprtsdom2n-&
&     remiprtn-grazprtn-pomprtn)/secperday
    dydtt(iprt15n) = (growprt15n-excrprtldom15n-excrprtsdom15n-&
&     excrprtsdom2_15n-remiprt15n-grazprt15n-pomprt15n)/secperday
    dydtt(iprtp) = (growprtp-excrprtldomp-excrprtsdomp-excrprtsdom2p-&
&     remiprtp-grazprtp-pomprtp)/secperday
!-----------------------------------------------------------------------
!      Metozoan Processes
!-----------------------------------------------------------------------
! 1. gross growth
    growmzc = grazprtc + graztrc + grazddac
    growmzn = grazprtn + graztrn + grazddan
    growmz15n = grazprt15n + graztr15n + grazdda15n
    growmzp = grazprtp + graztrp + grazddap
! 2. DOM excretion
    excrmzldomc = f_exmzldom*r_mzex*growmzc
    excrmzldomn = f_exmzldom*r_mzex*growmzn
    excrmzldom15n = f_exmzldom*r_mzex*growmz15n
    excrmzldomp = f_exmzldom*r_mzex*growmzp
    excrmzsdomc = (c1-f_exmzldom)*r_mzex*growmzc
    excrmzsdomn = (c1-f_exmzldom)*r_mzex*growmzn*y(imzn)/y(imzc)/q_mz_n
    excrmzsdom15n = excrmzsdomn*(rmz/(1.0d0+rmz))
    excrmzsdomp = (c1-f_exmzldom)*r_mzex*growmzp*y(imzp)/y(imzc)/q_mz_p
! 3. respiration
    respmz = r_mzresp_1*y(imzc) + r_mzresp_2*growmzc
    IF (c1 - y(imzn)/y(imzc)/q_mz_n .LT. c1 - y(imzp)/y(imzc)/q_mz_p) &
&   THEN
      temp = c1 - y(imzp)/y(imzc)/q_mz_p
    ELSE
      temp = c1 - y(imzn)/y(imzc)/q_mz_n
    END IF
    IF (temp .LT. c0) THEN
      temp = c0
    ELSE
      temp = temp
    END IF
    excrmzsdom2c = r_mzadju*y(imzc)*temp
    excrmzsdom2n = excrmzsdom2c*y(imzn)/y(imzc)*0.5d0
    excrmzsdom2_15n = excrmzsdom2n*(rmz/(1.0d0+rmz))
    excrmzsdom2p = excrmzsdom2c*y(imzp)/y(imzc)*0.5d0
    IF (r_mzremi*(y(imzn)-q_mz_n*y(imzc)) .LT. r_mzremi*(y(imzn)-q_mz_n/&
&       q_mz_p*y(imzp))) THEN
      remimzn = r_mzremi*(y(imzn)-q_mz_n/q_mz_p*y(imzp))
    ELSE
      remimzn = r_mzremi*(y(imzn)-q_mz_n*y(imzc))
    END IF
    IF (remimzn .LT. c0) THEN
      remimzn = c0
    ELSE
      remimzn = remimzn
    END IF
!  MZ beta  
    beta_mz_remi = rmz*(1.0d0-epsilon_remin/1000.0d0)
!  MZ15N
    remimz15n = remimzn*(beta_mz_remi/(1.0d0+beta_mz_remi))
    IF (r_mzremi*(y(imzp)-q_mz_p*y(imzc)) .LT. r_mzremi*(y(imzp)-q_mz_p/&
&       q_mz_n*y(imzn))) THEN
      remimzp = r_mzremi*(y(imzp)-q_mz_p/q_mz_n*y(imzn))
    ELSE
      remimzp = r_mzremi*(y(imzp)-q_mz_p*y(imzc))
    END IF
    IF (remimzp .LT. c0) THEN
      remimzp = c0
    ELSE
      remimzp = remimzp
    END IF
! 6. indissolved POM and refractory DOM production
    pommzc = r_mzpom*growmzc
    pommzn = q_pom_n*pommzc
    pommz15n = pommzn*(rmz/(1.0d0+rmz))
    pommzp = q_pom_p*pommzc
! 7. removal by higher-level zooplankton
    remvmzc = r_mzremv*y(imzc)*y(imzc)
    remvmzn = remvmzc/y(imzc)*y(imzn)
    remvmz15n = remvmzn*(rmz/(1.0d0+rmz))
    remvmzp = remvmzc/y(imzc)*y(imzp)
    pomhzc = f_hzpom*remvmzc
    pomhzn = f_hzpom*remvmzn
    pomhz15n = f_hzpom*remvmz15n
    pomhzp = f_hzpom*remvmzp
    excrhzsdomc = remvmzc*f_hzsdom
    excrhzsdomn = remvmzn*f_hzsdom
    excrhzsdom15n = remvmz15n*f_hzsdom
    excrhzsdomp = remvmzp*f_hzsdom
    remihzn = remvmzn - excrhzsdomn - pomhzn
    remihz15n = remvmz15n - excrhzsdom15n - pomhz15n
    remihzp = remvmzp - excrhzsdomp - pomhzp
! 8. new MZ
    dydtt(imzc) = (growmzc-excrmzldomc-excrmzsdomc-excrmzsdom2c-pommzc-&
&     remvmzc-respmz)/secperday
    dydtt(imzn) = (growmzn-excrmzldomn-excrmzsdomn-remimzn-excrmzsdom2n-&
&     pommzn-remvmzn)/secperday
    dydtt(imz15n) = (growmz15n-excrmzldom15n-excrmzsdom15n-remimz15n-&
&     excrmzsdom2_15n-pommz15n-remvmz15n)/secperday
    dydtt(imzp) = (growmzp-excrmzldomp-excrmzsdomp-remimzp-excrmzsdom2p-&
&     pommzp-remvmzp)/secperday
!-----------------------------------------------------------------------
!      Detritus Processes
!-----------------------------------------------------------------------
    disdetc = remin*y(idetc)
    disdetn = remin*y(idetn)*remin_prf_n
!  DET beta  
    beta_det_remi = rdet*(1.0d0-epsilon_remin/1000.0d0)
! DET15N
    disdet15n = disdetn*(beta_det_remi/(1.0d0+beta_det_remi))
!disDET15n    = disDETn * (rDET/(1+rDET))
    disdetp = remin*y(idetp)*remin_prf_p
    dydtt(idetc) = (pomspc+pomtrc+pomddac+pomunc+pomprtc+pommzc+pomhzc-&
&     disdetc)/secperday
    dydtt(idetn) = (pomspn+pomtrn+pomddan+pomunn+pomprtn+pommzn+pomhzn-&
&     disdetn)/secperday
    dydtt(idet15n) = (pomsp15n+pomtr15n+pomdda15n+pomun15n+pomprt15n+&
&     pommz15n+pomhz15n-disdet15n)/secperday
    dydtt(idetp) = (pomspp+pomtrp+pomddap+pomunp+pomprtp+pommzp+pomhzp-&
&     disdetp)/secperday
!-----------------------------------------------------------------------
!   Inorganic Nutrients Processes
!-----------------------------------------------------------------------
    nitrf = r_nitrf*y(inh4)
!--------------------------------------------------------------------
! nitrification
!--------------------------------------------------------------------
!  beta  
    u_nitrf = nitrf*dt/(y(inh4)+eps)
    IF (0.90d0 .GT. u_nitrf) THEN
      y25 = u_nitrf
    ELSE
      y25 = 0.90d0
    END IF
    IF (0.0d0 .LT. y25) THEN
      u_nitrf = y25
    ELSE
      u_nitrf = 0.0d0
    END IF
    IF (y(inh4) .LT. nh4_limit) THEN
! B
      factor_nitrf = 0.0d0
    ELSE IF (u_nitrf .LT. 1.0d-8) THEN
! A
      factor_nitrf = 1.0d0
    ELSE
      factor_nitrf = -((1.0d0-u_nitrf)/u_nitrf*LOG(1.0d0-u_nitrf))
    END IF
!smooth_factor = y(iNH4) / (y(iNH4) + N_abs_min)
!beta_nitrf = rNH4 * (1.0d0 - (epsilon_nitrf/1000.0d0) * factor_nitrf * smooth_factor)
    beta_nitrf = rnh4*(1.0d0-epsilon_nitrf/1000.0d0*factor_nitrf)
    nitrf15 = nitrf*(beta_nitrf/(1.0d0+beta_nitrf))
    dydtt(inh4) = (remiprtn+remimzn+remihzn+excrtr_nh4+excrdda_nh4+&
&     excrun_nh4-growspnh4-growtrnh4-growddanh4-growunnh4-fluxbanh4-&
&     nitrf)/secperday
    dydtt(ino3) = (-growspno3-growtrno3-growddano3-growunno3-fluxbano3+&
&     nitrf)/secperday
    dydtt(i15nh4) = (remiprt15n+remimz15n+remihz15n+excrtr_15nh4+&
&     excrdda_15nh4+excrun_15nh4-growsp15nh4-growtr15nh4-growdda15nh4-&
&     growun15nh4-fluxba15nh4-nitrf15)/secperday
    dydtt(i15no3) = (nitrf15-growsp15no3-growtr15no3-growdda15no3-&
&     growun15no3-fluxba15no3)/secperday
    dydtt(ipo4) = (remiprtp+remimzp+remihzp-growspp-growtrpo4-growddapo4&
&     -growunp-fluxbapo4)/secperday
!-----------------------------------------------------------------------
!      Dissolved Organic Matter (DOM) Processes
!-----------------------------------------------------------------------
    dydtt(ildomc) = (excrsp_1c+excrtr_1c+excrdda_1c+excrun_1c+&
&     excrprtldomc+excrmzldomc-growbaldoc+mortbac)/secperday
    dydtt(ildomn) = (excrsp_1n+excrtr_1n+excrdda_1n+excrun_1n+&
&     excrprtldomn+excrmzldomn-growbaldon+mortban)/secperday
    dydtt(ildom15n) = (excrsp_1_15n+excrtr_1_15n+excrdda_1_15n+&
&     excrun_1_15n+excrprtldom15n+excrmzldom15n-growba15ldon+mortba15n)/&
&     secperday
    dydtt(ildomp) = (excrsp_1p+excrtr_1p+excrdda_1p+excrun_1p+&
&     excrprtldomp+excrmzldomp-growbaldop+mortbap)/secperday
    dydtt(isdomc) = (excrsp_2c+excrtr_2c+excrdda_2c+excrun_2c+excrbac+&
&     excrprtsdomc+excrprtsdom2c+excrmzsdomc+excrmzsdom2c+excrhzsdomc+&
&     disdetc-growbasdoc)/secperday
    dydtt(isdomn) = (excrsp_2n+excrtr_2n+excrdda_2n+excrun_2n+excrban+&
&     excrprtsdomn+excrprtsdom2n+excrmzsdomn+excrmzsdom2n+excrhzsdomn+&
&     disdetn-growbasdon)/secperday
    dydtt(isdom15n) = (excrsp_2_15n+excrtr_2_15n+excrdda_2_15n+&
&     excrun_2_15n+excrba15n+excrprtsdom15n+excrprtsdom2_15n+&
&     excrmzsdom15n+excrmzsdom2_15n+excrhzsdom15n+disdet15n-growba15sdon&
&     )/secperday
    dydtt(isdomp) = (excrsp_2p+excrtr_2p+excrdda_2p+excrun_2p+excrbap+&
&     excrprtsdomp+excrprtsdom2p+excrmzsdomp+excrmzsdom2p+excrhzsdomp+&
&     disdetp-growbasdop)/secperday
    dydtt_diag(ipp) = (growspc+growtrc+growddac+growunc-respsp-resptr-&
&     respdda-respun-excrsp_1c-excrtr_1c-excrdda_1c-excrun_1c-excrsp_2c-&
&     excrtr_2c-excrdda_2c-excrun_2c)/secperday*12.d0
    dydtt_diag(iprbac) = (growbac-respba-mortbac)/secperday
    dydtt_diag(igrowspc) = growspc/secperday
    dydtt_diag(igrowspnh4) = growspnh4/secperday
    dydtt_diag(igrowspno3) = growspno3/secperday
    dydtt_diag(igrowspn) = growspn/secperday
    dydtt_diag(igrowsp15nh4) = growsp15nh4/secperday
    dydtt_diag(igrowsp15no3) = growsp15no3/secperday
    dydtt_diag(igrowsp15n) = growsp15n/secperday
    dydtt_diag(igrowspp) = growspp/secperday
    dydtt_diag(iexcrsp_1c) = excrsp_1c/secperday
    dydtt_diag(iexcrsp_1n) = excrsp_1n/secperday
    dydtt_diag(iexcrsp_1_15n) = excrsp_1_15n/secperday
    dydtt_diag(iexcrsp_1p) = excrsp_1p/secperday
    dydtt_diag(iexcrsp_2c) = excrsp_2c/secperday
    dydtt_diag(iexcrsp_2n) = excrsp_2n/secperday
    dydtt_diag(iexcrsp_2_15n) = excrsp_2_15n/secperday
    dydtt_diag(iexcrsp_2p) = excrsp_2p/secperday
    dydtt_diag(ipomspc) = pomspc/secperday
    dydtt_diag(ipomspn) = pomspn/secperday
    dydtt_diag(ipomsp15n) = pomsp15n/secperday
    dydtt_diag(ipomspp) = pomspp/secperday
